import React, { useState, useRef, useEffect } from 'react';
import { Language, ChatMessage, AIModelVersion, ChatSession, AIWorkMode, AIAttachment } from '../types';

interface AICoreProps {
  lang: Language;
}

export const AICore: React.FC<AICoreProps> = ({ lang }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [model, setModel] = useState<AIModelVersion>('gemini-3-flash-preview');

  // Attachments & Audio
  const [attachments, setAttachments] = useState<AIAttachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = {
    en: {
      newChat: "NEW SESSION",
      placeholder: "Broadcast message to core...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      history: "SESSIONS",
      modes: "WORK MODE",
      modeGen: "GENERAL",
      modeCode: "ENGINEER",
      modeData: "ANALYST",
      modeCreate: "CREATIVE",
      upload: "UPLOAD FILE",
      voice: "VOICE",
      listening: "LISTENING...",
      attach: "ATTACHED RES:",
      play: "PLAY",
      tts: "READ ALOUD",
      emptyState: "AWAITING INPUT STREAM...",
      processing: "PROCESSING...",
      error: "Error: Neural Link Failed.",
      user: "U",
      ai: "AI"
    },
    zh: {
      newChat: "新建会话",
      placeholder: "输入指令或提问...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      history: "历史会话",
      modes: "工作模式",
      modeGen: "通用助手",
      modeCode: "赛博工程师",
      modeData: "数据分析师",
      modeCreate: "创意总监",
      upload: "上传文件",
      voice: "语音输入",
      listening: "正在聆听...",
      attach: "已挂载资源:",
      play: "播放",
      tts: "朗读",
      emptyState: "等待输入信号...",
      processing: "计算中...",
      error: "错误：神经连接中断。",
      user: "我",
      ai: "AI"
    }
  }[lang];

  const modeLabels: Record<string, string> = {
      general: t.modeGen,
      coder: t.modeCode,
      analyst: t.modeData,
      creative: t.modeCreate
  };

  // --- Session Management ---
  useEffect(() => {
    fetchSessions();
  }, []);

  const fetchSessions = async () => {
    try {
      const res = await fetch('/api/ai/sessions');
      const data = await res.json();
      setSessions(data);
      if (data.length > 0 && !currentSessionId) {
          // Don't auto-select to allow "Fresh Start", or select first
          // setCurrentSessionId(data[0].id);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const createSession = async (mode: AIWorkMode = 'general') => {
    const res = await fetch('/api/ai/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode })
    });
    const newSession = await res.json();
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    setMessages([]);
    setAttachments([]);
  };

  const deleteSession = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      await fetch(`/api/ai/sessions/${id}`, { method: 'DELETE' });
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
          setCurrentSessionId(null);
          setMessages([]);
      }
  };

  // --- Messaging ---
  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if ((!textToSend.trim() && attachments.length === 0) || isLoading) return;

    // Auto-create session if none
    let activeSessionId = currentSessionId;
    if (!activeSessionId) {
        // Quick session creation
        const res = await fetch('/api/ai/sessions', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'general' }) });
        const newS = await res.json();
        setSessions(prev => [newS, ...prev]);
        activeSessionId = newS.id;
        setCurrentSessionId(newS.id);
    }

    const tempAttachments = [...attachments];

    // User Message
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      timestamp: Date.now(),
      attachments: tempAttachments
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachments([]);
    setIsLoading(true);

    // AI Placeholder
    const aiMsgId = (Date.now() + 1).toString();
    const aiMsgPlaceholder: ChatMessage = {
      id: aiMsgId,
      role: 'model',
      text: '',
      timestamp: Date.now() + 1,
      isThinking: true
    };
    setMessages(prev => [...prev, aiMsgPlaceholder]);

    try {
      const response = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId: activeSessionId,
          message: textToSend,
          attachments: tempAttachments, // Send metadata + base64 if small
          model: model,
          lang: lang // Pass language setting
        })
      });

      if (!response.body) throw new Error("No response");

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let done = false;
      let accumulatedText = '';

      while (!done) {
        const { value, done: doneReading } = await reader.read();
        done = doneReading;
        const chunkValue = decoder.decode(value, { stream: !done });
        accumulatedText += chunkValue;

        setMessages(prev => prev.map(msg => 
          msg.id === aiMsgId 
            ? { ...msg, text: accumulatedText, isThinking: false } 
            : msg
        ));
      }

      // Update Session Preview in list locally
      setSessions(prev => prev.map(s => s.id === activeSessionId ? { ...s, lastMessageAt: Date.now(), preview: accumulatedText.substring(0, 50) } : s));

    } catch (error) {
      console.error(error);
      setMessages(prev => prev.map(msg => 
        msg.id === aiMsgId ? { ...msg, text: t.error, isThinking: false } : msg
      ));
    } finally {
      setIsLoading(false);
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  };

  // --- Attachments ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];
          const formData = new FormData();
          formData.append('image', file);

          try {
              const res = await fetch('/api/upload', { method: 'POST', body: formData });
              const data = await res.json();

              // For small text files/images, we can also read client side for preview
              // For now, we trust server response
              const newAtt: AIAttachment = {
                  id: data.id,
                  type: file.type.startsWith('image/') ? 'image' : 'file',
                  url: data.url,
                  filename: data.filename,
                  mimeType: data.mimeType || file.type
              };
              setAttachments(prev => [...prev, newAtt]);
          } catch (e) { console.error(e); alert("Upload Failed"); }
      }
  };

  // --- Voice Input (STT) ---
  const startRecording = async () => {
      try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          const mediaRecorder = new MediaRecorder(stream);
          mediaRecorderRef.current = mediaRecorder;
          const chunks: Blob[] = [];

          mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
          mediaRecorder.onstop = async () => {
              const blob = new Blob(chunks, { type: 'audio/webm' }); // Chrome uses webm
              const formData = new FormData();
              formData.append('audio', blob, 'voice_input.webm');

              setIsLoading(true); // Temp loading while transcribing
              try {
                  const res = await fetch('/api/ai/transcribe', { method: 'POST', headers: { 'api-key': 'internal' }, body: formData });
                  const data = await res.json();
                  if (data.text) {
                      handleSend(data.text); // Auto send transcript
                  }
              } catch (e) { console.error(e); } finally { setIsLoading(false); }
          };

          mediaRecorder.start();
          setIsRecording(true);
      } catch (e) { alert("Mic Access Denied"); }
  };

  const stopRecording = () => {
      mediaRecorderRef.current?.stop();
      setIsRecording(false);
  };

  // --- TTS ---
  const playTTS = async (text: string) => {
      try {
          // Strip Markdown images/video from TTS
          const cleanText = text.replace(/!\[.*?\]\(.*?\)/g, '');

          const res = await fetch('/api/ai/tts', { 
              method: 'POST', 
              headers: { 'Content-Type': 'application/json' }, 
              body: JSON.stringify({ text: cleanText }) 
          });
          const data = await res.json();
          if (data.audio) {
              const audio = new Audio(`data:audio/wav;base64,${data.audio}`);
              audio.play();
          }
      } catch (e) { console.error(e); }
  };

  // --- Message Renderer with Markdown Image/Video Support ---
  const renderMessageContent = (text: string) => {
      // Regex to find ![alt](url)
      const parts = text.split(/(!\[.*?\]\(.*?\))/g);
      return parts.map((part, index) => {
          const imgMatch = part.match(/!\[(.*?)\]\((.*?)\)/);
          if (imgMatch) {
              const alt = imgMatch[1];
              const url = imgMatch[2];

              // Handle MP4 Video
              if (url.endsWith('.mp4') || alt.toLowerCase().includes('video')) {
                   return (
                      <div key={index} className="my-2 rounded-lg overflow-hidden border border-purple-600 shadow-lg relative group">
                          <video src={url} controls className="w-full max-h-64 bg-black/50" />
                          <div className="bg-purple-900/50 p-1 text-[10px] text-purple-300 font-code text-center">GENERATED_VEO_ASSET</div>
                      </div>
                   );
              }

              return (
                  <div key={index} className="my-2 rounded-lg overflow-hidden border border-slate-600 shadow-lg">
                      <img src={url} alt={alt} className="w-full max-h-64 object-contain bg-black/20" />
                      <div className="bg-slate-900/50 p-1 text-[10px] text-slate-500 font-code text-center">GENERATED_ASSET</div>
                  </div>
              );
          }
          return <span key={index}>{part}</span>;
      });
  };

  // --- Render Helpers ---
  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  return (
    <div className="flex h-full bg-[#020617] text-slate-200 overflow-hidden font-sans relative">

      {/* --- SIDEBAR --- */}
      <div className="w-16 md:w-64 flex flex-col bg-slate-900/50 border-r border-cyan-900/30 backdrop-blur-md z-20 transition-all">
        <div className="p-4 flex flex-col gap-2">
          <button onClick={() => createSession('general')} className="w-full flex items-center justify-center md:justify-start gap-3 px-3 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-tech text-xs tracking-widest uppercase shadow-lg transition-all clip-button">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden md:inline">{t.newChat}</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
           <div className="hidden md:block text-[10px] text-slate-500 font-code uppercase tracking-widest mb-2 px-2">{t.history}</div>
           <div className="space-y-1">
             {sessions.map(s => (
               <div key={s.id} onClick={() => { setCurrentSessionId(s.id); setMessages([]); }} className={`group relative p-2 md:p-3 cursor-pointer border-l-2 transition-all ${currentSessionId === s.id ? 'bg-slate-800 border-cyan-500 text-cyan-100' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}>
                  <div className="flex justify-between items-center">
                      <div className="font-bold text-xs truncate w-full pr-6">{s.title || "Untitled Link"}</div>
                      <button onClick={(e) => deleteSession(s.id, e)} className="absolute right-2 opacity-0 group-hover:opacity-100 text-slate-600 hover:text-rose-500">×</button>
                  </div>
                  <div className="hidden md:block text-[10px] font-code truncate opacity-70 mt-1">{s.preview}</div>
                  <div className="hidden md:flex gap-2 mt-1">
                      <span className={`text-[8px] px-1 rounded border ${s.mode==='coder'?'border-purple-500 text-purple-400':s.mode==='analyst'?'border-emerald-500 text-emerald-400':'border-slate-600'}`}>{s.mode.toUpperCase()}</span>
                  </div>
               </div>
             ))}
           </div>
        </div>

        {/* Mode Selector (Quick Switch) */}
        <div className="p-2 border-t border-slate-800 hidden md:block">
            <div className="text-[10px] text-slate-500 font-code mb-2">{t.modes}</div>
            <div className="grid grid-cols-2 gap-1">
                {(['general', 'coder', 'analyst', 'creative'] as AIWorkMode[]).map(m => (
                    <button key={m} onClick={() => createSession(m)} className="text-[9px] border border-slate-700 p-1 hover:border-cyan-500 hover:text-cyan-400 uppercase transition-colors">
                        {modeLabels[m]} 
                    </button>
                ))}
            </div>
        </div>
      </div>

      {/* --- MAIN CHAT AREA --- */}
      <div className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

        {/* Header */}
        <div className="h-14 border-b border-cyan-900/30 bg-slate-900/80 backdrop-blur-md flex items-center justify-between px-6 z-30">
           <div className="flex items-center gap-2">
              <span className="text-cyan-400 font-tech text-lg">AI_CORE</span>
              <span className="text-slate-600 font-thin">/</span>
              <select value={model} onChange={(e) => setModel(e.target.value as AIModelVersion)} className="bg-transparent text-xs font-code text-slate-300 focus:outline-none uppercase cursor-pointer hover:text-cyan-400">
                 <option value="gemini-3-flash-preview">{t.modelFlash}</option>
                 <option value="gemini-3-pro-preview">{t.modelPro}</option>
              </select>
           </div>
           <div className="flex gap-4">
              {currentSessionId && <span className="text-xs font-code text-slate-500 uppercase border px-2 py-0.5 border-slate-700 rounded-full">{sessions.find(s=>s.id===currentSessionId)?.mode} MODE</span>}
           </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-0 animate-[fadeIn_0.5s_ease-out_forwards]">
               <div className="w-20 h-20 mb-6 relative">
                  <div className="absolute inset-0 border-t-2 border-cyan-500 rounded-full animate-spin"></div>
                  <div className="absolute inset-2 border-b-2 border-purple-500 rounded-full animate-[spin_3s_linear_infinite]"></div>
                  <div className="absolute inset-0 flex items-center justify-center font-tech text-2xl text-white">AI</div>
               </div>
               <div className="text-slate-500 font-code text-sm uppercase">{t.emptyState}</div>
            </div>
          ) : (
            <div className="max-w-4xl mx-auto space-y-8">
               {messages.map((msg) => (
                 <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-8 h-8 flex-shrink-0 flex items-center justify-center rounded-sm border ${msg.role === 'user' ? 'bg-cyan-900/20 border-cyan-500/50 text-cyan-400' : 'bg-purple-900/20 border-purple-500/50 text-purple-400'}`}>
                       {msg.role === 'user' ? t.user : t.ai}
                    </div>

                    <div className={`flex flex-col max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>

                       {/* Attachments Display */}
                       {msg.attachments && msg.attachments.length > 0 && (
                           <div className="flex flex-wrap gap-2 mb-2 justify-end">
                               {msg.attachments.map(att => (
                                   <div key={att.id} className="relative group border border-slate-700 bg-slate-900 rounded overflow-hidden w-24 h-24 flex items-center justify-center">
                                       {att.type === 'image' ? (
                                           <img src={att.url} className="w-full h-full object-cover" />
                                       ) : (
                                           <div className="text-[9px] text-center p-1 text-slate-400 break-all">{att.filename}</div>
                                       )}
                                   </div>
                               ))}
                           </div>
                       )}

                       <div className={`p-4 text-sm font-sans leading-relaxed shadow-lg whitespace-pre-wrap ${msg.role === 'user' ? 'bg-cyan-950/30 border border-cyan-500/20 text-cyan-100 rounded-bl-xl' : 'bg-slate-900/80 border border-slate-700 text-slate-300 rounded-br-xl'}`}>
                          {msg.isThinking ? <span className="animate-pulse text-purple-400">{t.processing}</span> : renderMessageContent(msg.text)}
                       </div>

                       {msg.role === 'model' && !msg.isThinking && (
                           <button onClick={() => playTTS(msg.text)} className="mt-1 text-[10px] text-slate-600 hover:text-cyan-400 flex items-center gap-1 cursor-pointer transition-colors">
                               <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                               {t.tts}
                           </button>
                       )}
                    </div>
                 </div>
               ))}
               <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 bg-slate-900/90 backdrop-blur-xl border-t border-cyan-900/30 relative z-30">
           {/* Attachment Preview Bar */}
           {attachments.length > 0 && (
               <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
                   <span className="text-xs text-cyan-500 font-code self-center mr-2">{t.attach}</span>
                   {attachments.map((att, i) => (
                       <div key={i} className="relative bg-slate-800 border border-slate-600 rounded p-1 w-12 h-12 flex items-center justify-center shrink-0">
                           {att.type==='image' ? <img src={att.url} className="w-full h-full object-cover opacity-70" /> : <span className="text-[8px] text-slate-400">FILE</span>}
                           <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-[10px] flex items-center justify-center">×</button>
                       </div>
                   ))}
               </div>
           )}

           <div className="max-w-4xl mx-auto flex gap-3 items-end">
              {/* Tools: Upload & Voice */}
              <div className="flex gap-2 pb-2">
                  <button onClick={() => fileInputRef.current?.click()} className="text-slate-500 hover:text-cyan-400 p-2 border border-transparent hover:border-slate-700 rounded transition-all">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

                  <button 
                    onMouseDown={startRecording} 
                    onMouseUp={stopRecording} 
                    className={`p-2 rounded border transition-all ${isRecording ? 'bg-red-900/50 text-red-500 border-red-500 animate-pulse' : 'text-slate-500 hover:text-cyan-400 border-transparent hover:border-slate-700'}`}
                  >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                  </button>
              </div>

              <div className="relative flex-1 group">
                 <div className="absolute -top-1 -left-1 w-2 h-2 border-t border-l border-cyan-500/50"></div>
                 <div className="absolute -bottom-1 -right-1 w-2 h-2 border-b border-r border-cyan-500/50"></div>

                 <textarea
                   ref={inputRef}
                   value={input}
                   onChange={(e) => setInput(e.target.value)}
                   onKeyDown={(e) => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                   placeholder={isRecording ? t.listening : t.placeholder}
                   className="w-full bg-black/60 border border-slate-700 text-white p-3 pr-10 focus:outline-none focus:border-cyan-500/50 transition-all font-sans resize-none custom-scrollbar max-h-32 min-h-[48px] rounded-none"
                   rows={1}
                 />
              </div>

              <button 
                onClick={() => handleSend()}
                disabled={isLoading || (!input.trim() && attachments.length===0)}
                className={`p-3 mb-1 bg-cyan-900/20 border border-cyan-500/30 text-cyan-400 hover:bg-cyan-600 hover:text-white transition-all ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Dropzone } from './components/Dropzone';
import { Controls } from './components/Controls';
import { StockDashboard } from './components/StockDashboard';
import { AICore } from './components/AICore';
import { ImageFormat, ProcessOptions, UploadResponse, ProcessResponse, Language, RawPixelFormat } from './types';

const defaultOptions: ProcessOptions = {
  format: ImageFormat.ORIGINAL,
  quality: 85,
  width: null,
  height: null,
  maintainAspectRatio: true,
  resizeMode: 'cover',
  rotate: 0,
  flipX: false,
  flipY: false,
  grayscale: false,
  blur: 0,
  sharpen: false,
  watermarkText: '',
  watermarkPosition: 'bottom-right',
  rawWidth: undefined,
  rawHeight: undefined,
  rawPixelFormat: 'uyvy',
  aiTask: 'vision',
  aiPrompt: ''
};

type AppMode = 'image' | 'data' | 'ai';

function App() {
  const [lang, setLang] = useState<Language>('en');
  const [mode, setMode] = useState<AppMode>('image');

  // Security States
  const [dataUnlocked, setDataUnlocked] = useState(false);
  const [aiUnlocked, setAiUnlocked] = useState(false); // Added AI Lock
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordInput, setPasswordInput] = useState('');
  const [unlockTarget, setUnlockTarget] = useState<'data' | 'ai' | null>(null); // Track what we are unlocking

  // Image Core States
  const [currentFile, setCurrentFile] = useState<UploadResponse | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [options, setOptions] = useState<ProcessOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessResponse | null>(null);
  const [error, setError] = useState<string | null>(null); // New Error State
  const [totalProcessed, setTotalProcessed] = useState(0);

  const t = {
    en: {
      appTitle: "TUKUKU",
      sloganTitle: "IMAGE PROCESSOR",
      uploadFailed: "CRITICAL ERROR: UPLOAD FAILED",
      processFailed: "PROCESSING ERROR",
      processedSuccess: "RENDER_COMPLETE",
      preview: "VISUAL_FEED",
      noPreview: "NO VISUAL FEED FOR RAW DATA",
      originalSize: "INPUT_SIZE",
      newSize: "OUTPUT_SIZE",
      savings: "EFFICIENCY",
      startOver: "RESET_SYSTEM",
      download: "EXTRACT_DATA",
      serverDesc: "SECURE SERVER CONNECTION :: ESTABLISHED",
      status: "STATUS",
      coord: "COORD",
      auto: "AUTO",
      modeImage: "IMAGE_CORE",
      modeData: "DATA_CORE",
      modeAI: "AI_CORE",
      enterPwd: "ENTER ACCESS CODE",
      unlock: "UNLOCK",
      accessDenied: "ACCESS DENIED: INVALID TOKEN",
      aiResult: "NEURAL ANALYSIS",
      error: "SYSTEM ALERT"
    },
    zh: {
      appTitle: "图酷酷",
      sloganTitle: "图像处理器",
      uploadFailed: "严重错误：上传失败",
      processFailed: "处理错误",
      processedSuccess: "渲染完毕",
      preview: "视觉反馈",
      noPreview: "RAW 数据无视觉反馈",
      originalSize: "输入体积",
      newSize: "输出体积",
      savings: "效率提升",
      startOver: "重置系统",
      download: "提取数据",
      serverDesc: "安全连接 :: 已建立",
      status: "状态",
      coord: "尺寸",
      auto: "自动",
      modeImage: "图像核心",
      modeData: "数据核心",
      modeAI: "AI 核心",
      enterPwd: "输入访问密钥",
      unlock: "解锁",
      accessDenied: "访问拒绝：无效的密钥",
      aiResult: "神经分析结果",
      error: "系统警报"
    }
  }[lang];

  useEffect(() => {
    fetch('/api/stats')
      .then(res => res.json())
      .then(data => {
        if (data.processedCount) setTotalProcessed(data.processedCount);
      })
      .catch(err => console.error("Failed to load stats", err));
  }, []);

  const getFormatFromExt = (filename: string): RawPixelFormat => {
      const lower = filename.toLowerCase();
      if (lower.endsWith('.uyvy')) return 'uyvy';
      if (lower.endsWith('.nv21')) return 'nv21';
      if (lower.endsWith('.rgba')) return 'rgba';
      if (lower.endsWith('.bgra')) return 'bgra';
      if (lower.endsWith('.rgb')) return 'rgb';
      if (lower.endsWith('.bgr')) return 'bgr';
      return 'uyvy'; 
  };

  const isRawFormat = (filename: string) => {
      const exts = ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'];
      return exts.some(ext => filename.toLowerCase().endsWith(ext));
  };

  const handleFileUpload = async (file: File) => {
    setIsUploading(true);
    setResult(null);
    setError(null);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        let errorMessage = `${t.uploadFailed} (${response.status})`;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
          errorMessage = `${t.uploadFailed}: ${response.statusText || response.status}`;
        }
        throw new Error(errorMessage);
      }

      const data: UploadResponse = await response.json();
      setCurrentFile(data);

      const suggestedFormat = getFormatFromExt(data.originalName);
      const isRaw = isRawFormat(data.originalName);

      setOptions({
        ...defaultOptions,
        format: ImageFormat.ORIGINAL,
        width: data.width || null,
        height: data.height || null,
        rawWidth: isRaw ? (data.width || 1920) : undefined,
        rawHeight: isRaw ? (data.height || 1080) : undefined,
        rawPixelFormat: suggestedFormat
      });
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.uploadFailed);
    } finally {
      setIsUploading(false);
    }
  };

  const handleProcess = async () => {
    if (!currentFile) return;

    setIsProcessing(true);
    setError(null);
    try {
      const response = await fetch('/api/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          options
        })
      });

      if (!response.ok) {
        let errorMessage = t.processFailed;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
           errorMessage = `${t.processFailed}: ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const data: ProcessResponse = await response.json();

      await new Promise((resolve) => {
        const img = new Image();
        if (data.url) {
            img.src = data.url;
            img.onload = resolve;
            img.onerror = resolve; 
        } else {
            resolve(true);
        }
      });

      setResult(data);
      setTotalProcessed(prev => prev + 1);

    } catch (error: any) {
      console.error(error);
      alert(error.message || t.processFailed);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAIProcess = async () => {
    if (!currentFile) return;
    setIsProcessing(true);
    setResult(null); 
    setError(null);

    try {
      const response = await fetch('/api/ai-process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          task: options.aiTask,
          prompt: options.aiPrompt
        })
      });

      if (!response.ok) {
         const errorData = await response.json();
         throw new Error(errorData.error || t.processFailed);
      }

      const data: ProcessResponse = await response.json();
      setResult(data);
      setTotalProcessed(prev => prev + 1);

    } catch (error: any) {
      console.error(error);
      setError(error.message); // Set UI error state instead of alert
    } finally {
      setIsProcessing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleReset = () => {
    setCurrentFile(null);
    setResult(null);
    setError(null);
    setOptions(defaultOptions);
  };

  const getBitDepthLabel = (depth?: string) => {
    if (!depth) return null;
    if (depth === 'uchar') return null; 
    if (depth === 'ushort' || depth === 'short') return '16-BIT';
    if (depth === 'float') return '32-BIT FLOAT';
    if (depth === 'uint' || depth === 'int') return '32-BIT INT';
    return depth.toUpperCase();
  };

  const toggleLang = () => {
    setLang(prev => prev === 'en' ? 'zh' : 'en');
  };

  const handleModeSwitch = (newMode: AppMode) => {
    if (newMode === 'data' && !dataUnlocked) {
      setUnlockTarget('data');
      setShowPasswordModal(true);
    } else if (newMode === 'ai' && !aiUnlocked) {
      setUnlockTarget('ai');
      setShowPasswordModal(true);
    } else {
      setMode(newMode);
    }
  };

  const handleUnlock = () => {
    if (unlockTarget === 'data' && passwordInput === '666888') {
      setDataUnlocked(true);
      setShowPasswordModal(false);
      setMode('data');
      setPasswordInput('');
    } else if (unlockTarget === 'ai' && passwordInput === '666666') {
      setAiUnlocked(true);
      setShowPasswordModal(false);
      setMode('ai');
      setPasswordInput('');
    } else {
      alert(t.accessDenied);
      setShowPasswordModal(false); // keep open? usually better to keep open for retry, but follow pattern
      setPasswordInput('');
    }
  };

  return (
    <div className="flex flex-col h-full bg-transparent text-slate-300 font-sans selection:bg-cyan-500/30 selection:text-cyan-100">
      {/* Password Modal */}
      {showPasswordModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
           <div className={`bg-slate-900 border p-8 max-w-sm w-full shadow-[0_0_50px_rgba(0,0,0,0.5)] relative overflow-hidden ${unlockTarget === 'ai' ? 'border-emerald-500/50 shadow-[0_0_50px_rgba(16,185,129,0.3)]' : 'border-cyan-500/50 shadow-[0_0_50px_rgba(6,182,212,0.3)]'}`}>
               <div className={`absolute top-0 left-0 w-full h-1 bg-gradient-to-r animate-pulse ${unlockTarget === 'ai' ? 'from-emerald-500 via-green-500 to-emerald-500' : 'from-cyan-500 via-purple-500 to-cyan-500'}`}></div>
               <h3 className={`text-xl font-tech mb-6 text-center tracking-widest ${unlockTarget === 'ai' ? 'text-emerald-400' : 'text-cyan-400'}`}>{t.enterPwd}</h3>
               <input 
                 type="password" 
                 value={passwordInput}
                 onChange={(e) => setPasswordInput(e.target.value)}
                 className="w-full bg-black border border-slate-600 text-white px-4 py-2 font-code text-center tracking-[0.5em] mb-6 focus:outline-none focus:border-cyan-500"
                 autoFocus
                 onKeyDown={(e) => e.key === 'Enter' && handleUnlock()}
               />
               <div className="flex gap-4">
                  <button onClick={() => { setShowPasswordModal(false); setUnlockTarget(null); }} className="flex-1 py-2 font-code text-slate-500 hover:text-white border border-transparent hover:border-slate-500">CANCEL</button>
                  <button onClick={handleUnlock} className={`flex-1 py-2 text-white font-tech tracking-wider clip-button ${unlockTarget === 'ai' ? 'bg-emerald-600 hover:bg-emerald-500' : 'bg-cyan-600 hover:bg-cyan-500'}`}>{t.unlock}</button>
               </div>
           </div>
        </div>
      )}

      {/* Header */}
      <header className="border-b border-cyan-900/50 bg-[#020617]/90 backdrop-blur-md py-4 px-6 shadow-[0_0_20px_rgba(6,182,212,0.1)] relative z-20">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={handleReset}>
            <div className={`w-10 h-10 border rounded-none flex items-center justify-center relative overflow-hidden transition-all duration-300 ${mode === 'image' ? 'bg-cyan-900/30 border-cyan-500' : mode === 'data' ? 'bg-purple-900/30 border-purple-500' : 'bg-emerald-900/30 border-emerald-500'}`}>
               <div className={`absolute inset-0 animate-pulse ${mode === 'image' ? 'bg-cyan-400/10' : mode === 'data' ? 'bg-purple-400/10' : 'bg-emerald-400/10'}`}></div>
               {mode === 'image' && (
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-cyan-400 relative z-10"><path strokeLinecap="square" strokeLinejoin="miter" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456zM16.894 20.567L16.5 21.75l-.394-1.183a2.25 2.25 0 00-1.423-1.423L13.5 18.75l1.183-.394a2.25 2.25 0 001.423-1.423l.394-1.183.394 1.183a2.25 2.25 0 001.423 1.423l1.183.394-1.183.394a2.25 2.25 0 00-1.423 1.423z" /></svg>
               )}
               {mode === 'data' && (
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-purple-400 relative z-10"><path strokeLinecap="square" strokeLinejoin="miter" d="M3.75 6A2.25 2.25 0 016 3.75h2.25A2.25 2.25 0 0110.5 6v2.25a2.25 2.25 0 01-2.25 2.25H6a2.25 2.25 0 01-2.25-2.25V6zM3.75 15.75A2.25 2.25 0 016 13.5h2.25a2.25 2.25 0 012.25 2.25V18a2.25 2.25 0 01-2.25 2.25H6A2.25 2.25 0 013.75 18v-2.25zM13.5 6a2.25 2.25 0 012.25-2.25H18A2.25 2.25 0 0120.25 6v2.25A2.25 2.25 0 0118 10.5h-2.25a2.25 2.25 0 01-2.25-2.25V6zM13.5 15.75a2.25 2.25 0 012.25-2.25H18a2.25 2.25 0 012.25 2.25V18A2.25 2.25 0 0118 20.25h-2.25A2.25 2.25 0 0113.5 18v-2.25z" /></svg>
               )}
               {mode === 'ai' && (
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-emerald-400 relative z-10"><path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
               )}
            </div>
            <div>
              <h1 className="text-2xl font-tech font-bold tracking-widest text-cyan-50 hover-glitch" data-text={t.appTitle}>{t.appTitle}</h1>
              <div className={`h-0.5 w-full bg-gradient-to-r to-transparent transition-colors duration-500 ${mode === 'image' ? 'from-cyan-500' : mode === 'data' ? 'from-purple-500' : 'from-emerald-500'}`}></div>
            </div>
          </div>

          <div className="hidden md:flex bg-slate-900 border border-slate-700 p-1 rounded-sm">
             <button onClick={() => handleModeSwitch('ai')} className={`px-4 py-1 text-xs font-tech tracking-wider transition-all ${mode === 'ai' ? 'bg-emerald-600 text-white shadow-[0_0_10px_rgba(16,185,129,0.5)]' : 'text-slate-500 hover:text-slate-300'}`}>{t.modeAI}</button>
             <button onClick={() => handleModeSwitch('image')} className={`px-4 py-1 text-xs font-tech tracking-wider transition-all ${mode === 'image' ? 'bg-cyan-600 text-white shadow-[0_0_10px_rgba(6,182,212,0.5)]' : 'text-slate-500 hover:text-slate-300'}`}>{t.modeImage}</button>
             <button onClick={() => handleModeSwitch('data')} className={`px-4 py-1 text-xs font-tech tracking-wider transition-all ${mode === 'data' ? 'bg-purple-600 text-white shadow-[0_0_10px_rgba(168,85,247,0.5)]' : 'text-slate-500 hover:text-slate-300'}`}>{t.modeData}</button>
          </div>

          <div className="flex items-center gap-6">
             <button onClick={toggleLang} className="flex items-center justify-center px-4 py-1.5 text-xs font-code font-bold text-cyan-400 border border-cyan-800 hover:bg-cyan-900/30 hover:border-cyan-500 transition-all uppercase tracking-wider">[{lang === 'en' ? 'CN' : 'EN'}]</button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden relative z-10">
        <div className="absolute inset-0 overflow-y-auto custom-scrollbar">

          {mode === 'data' ? (
             <div className="max-w-7xl mx-auto h-full min-h-[calc(100vh-80px)]"><StockDashboard lang={lang} /></div>
          ) : mode === 'ai' ? (
             <div className="h-full min-h-[calc(100vh-80px)] bg-[#020617]"><AICore lang={lang} /></div>
          ) : (
            <div className="max-w-7xl mx-auto p-6 h-full min-h-[calc(100vh-80px)]">
              {!currentFile ? (
                <div className="h-full flex flex-col justify-center items-center max-w-3xl mx-auto mt-20 md:mt-0">
                  <div className="w-full text-center mb-12 relative">
                     <h2 className="text-5xl md:text-6xl font-tech font-black text-transparent bg-clip-text bg-gradient-to-b from-white to-slate-500 mb-6 tracking-tighter drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]">{t.sloganTitle}</h2>
                  </div>
                  <div className="w-full max-w-xl"><Dropzone onFileSelect={handleFileUpload} isUploading={isUploading} lang={lang} processedCount={totalProcessed} /></div>
                </div>
              ) : (
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full pb-10">
                  <div className="lg:col-span-4 h-full max-h-[850px]">
                    <Controls 
                      options={options} 
                      setOptions={setOptions} 
                      onProcess={handleProcess}
                      onAIProcess={handleAIProcess}
                      isProcessing={isProcessing}
                      originalDimensions={{ width: currentFile.width || 0, height: currentFile.height || 0 }}
                      lang={lang}
                      inputFormat={currentFile.originalName} 
                    />
                  </div>

                  <div className="lg:col-span-8 flex flex-col gap-6">
                    <div className="bg-slate-900/50 border border-slate-700 rounded-none flex-1 flex flex-col relative overflow-hidden group h-[500px] lg:h-auto">
                      <div className="absolute top-0 left-0 p-2 z-20 flex gap-1">
                          <div className="w-16 h-1 bg-cyan-600/50"></div>
                          <div className="w-4 h-1 bg-cyan-600/50"></div>
                      </div>
                      <div className="absolute bottom-0 right-0 p-2 z-20 text-[10px] font-code text-slate-500 uppercase">{t.coord}: {options.width || t.auto} x {options.height || t.auto}</div>

                      <div className="relative z-10 w-full h-full flex items-center justify-center p-8 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
                        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-cyan-900/5 to-transparent pointer-events-none"></div>

                        {isProcessing && (
                           <div className="absolute inset-0 z-30 pointer-events-none"><div className="scanner-overlay"></div><div className="scanner-line"></div></div>
                        )}

                        {error && (
                            <div className="absolute inset-0 z-50 flex items-center justify-center p-8 bg-black/80 backdrop-blur-md">
                                <div className="border border-rose-500 bg-rose-950/30 p-8 max-w-lg text-center shadow-[0_0_30px_rgba(244,63,94,0.3)]">
                                    <h3 className="text-xl font-tech text-rose-500 uppercase tracking-widest mb-4 animate-pulse">{t.error}</h3>
                                    <p className="text-white font-code text-sm leading-relaxed">{error}</p>
                                </div>
                            </div>
                        )}

                        {result && !error ? (
                           <div className="flex flex-col items-center relative w-full h-full justify-center">
                              {/* --- AI TEXT RESULT --- */}
                              {result.aiText && (
                                <div className="absolute inset-0 z-40 bg-black/80 backdrop-blur-md p-8 overflow-y-auto">
                                   <h3 className="text-purple-400 font-tech uppercase tracking-widest mb-4 border-b border-purple-500/30 pb-2">{t.aiResult}</h3>
                                   <p className="text-white font-code text-sm leading-relaxed whitespace-pre-wrap">{result.aiText}</p>
                                </div>
                              )}

                              {/* --- VIDEO RESULT --- */}
                              {result.mimeType === 'video/mp4' ? (
                                <video controls autoPlay loop className="max-h-[500px] w-full shadow-[0_0_30px_rgba(168,85,247,0.3)] border border-purple-500">
                                   <source src={result.url} type="video/mp4" />
                                   Your browser does not support the video tag.
                                </video>
                              ) : (
                                /* --- IMAGE RESULT --- */
                                <img 
                                  src={result.url} 
                                  alt="Processed" 
                                  className="max-h-[500px] w-full object-contain shadow-[0_0_30px_rgba(6,182,212,0.15)] border border-slate-700" 
                                />
                              )}

                              <div className="absolute top-4 right-4 z-40 pointer-events-none">
                                  <div className="flex items-center gap-3 bg-cyan-950/80 border-l-2 border-cyan-400 px-4 py-2 backdrop-blur-md shadow-[0_0_15px_rgba(6,182,212,0.2)] animate-pulse">
                                      <div className="flex flex-col items-end">
                                          <span className="text-[10px] font-tech text-cyan-400 tracking-widest">{t.status}</span>
                                          <span className="text-sm font-code font-bold text-white tracking-wider">{t.processedSuccess}</span>
                                      </div>
                                      <div className="w-2 h-2 bg-cyan-400 shadow-[0_0_10px_#06b6d4] rounded-full"></div>
                                  </div>
                              </div>
                           </div>
                        ) : !error && (
                          <div className="relative w-full h-full flex items-center justify-center">
                             {isRawFormat(currentFile.filename) ? (
                                <div className="flex flex-col items-center justify-center p-8 border border-slate-700 bg-slate-900/80 backdrop-blur-sm relative z-20">
                                   <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-16 h-16 text-yellow-600 mb-4 opacity-80"><path strokeLinecap="square" strokeLinejoin="miter" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m0 12.75h7.5m-7.5 3H12M10.5 2.25H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" /></svg>
                                   <span className="text-yellow-500 font-tech tracking-wider text-lg animate-pulse">{t.noPreview}</span>
                                   <span className="text-yellow-700 font-code text-xs mt-2 text-center max-w-xs uppercase border-t border-yellow-800/50 pt-2">{lang === 'en' ? 'Awaiting parameter configuration...' : '等待参数配置...'}</span>
                                </div>
                             ) : (
                               <>
                                 <img 
                                   src={currentFile.url} 
                                   alt="Original" 
                                   decoding="async"
                                   className="max-h-[500px] object-contain shadow-2xl border border-slate-700 transition-all duration-300 z-20" 
                                   style={{
                                     transform: `rotate(${options.rotate}deg) scaleX(${options.flipX ? -1 : 1}) scaleY(${options.flipY ? -1 : 1})`,
                                     filter: `grayscale(${options.grayscale ? 1 : 0}) blur(${options.blur}px) ${options.sharpen ? 'contrast(1.2) brightness(1.1)' : ''}`
                                   }} 
                                 />
                                 <div className="absolute top-4 right-4 bg-black/70 border border-cyan-500/30 text-cyan-400 text-[10px] font-code px-3 py-1 backdrop-blur-md uppercase tracking-widest z-20">● {t.preview}</div>
                               </>
                             )}
                          </div>
                        )}
                      </div>
                    </div>

                    {result && !error && (
                      <div className="bg-slate-900/80 border-t border-b border-cyan-900/50 p-4 flex items-center justify-between relative backdrop-blur-md">
                         <div className="absolute top-0 left-0 w-1 h-full bg-cyan-500"></div>

                         <div className="flex items-center gap-8">
                            <div className="text-xs font-code">
                               <p className="text-slate-500 uppercase tracking-wider mb-1">{t.originalSize}</p>
                               <p className="text-slate-200">{formatSize(currentFile.size)} {getBitDepthLabel(currentFile.depth) && (<span className="text-slate-600 ml-2">[{getBitDepthLabel(currentFile.depth)}]</span>)}</p>
                            </div>

                            <div className="text-2xl text-slate-700 font-thin">/</div>

                            {/* Only show output size if a file was actually generated (not just text) */}
                            {result.size && (
                              <>
                                <div className="text-xs font-code">
                                  <p className="text-slate-500 uppercase tracking-wider mb-1">{t.newSize}</p>
                                  <p className="text-cyan-400 font-bold glow-text">{formatSize(result.size)}</p>
                                </div>
                                <div className="text-2xl text-slate-700 font-thin">/</div>
                                <div className="text-xs font-code">
                                  <p className="text-slate-500 uppercase tracking-wider mb-1">{t.savings}</p>
                                  <p className="text-green-400">{currentFile.size > result.size ? Math.round(((currentFile.size - result.size) / currentFile.size) * 100) + '%' : 'N/A'}</p>
                                </div>
                              </>
                            )}
                         </div>

                         <div className="flex gap-4">
                           <button onClick={handleReset} className="px-4 py-2 text-xs font-code font-bold text-slate-400 hover:text-white border border-transparent hover:border-slate-500 transition-all uppercase tracking-wider">{t.startOver}</button>
                           {result.url && (
                             <a href={result.url} download={result.filename} className="flex items-center gap-2 bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-2 font-tech font-bold uppercase tracking-widest text-xs clip-button shadow-[0_0_15px_rgba(6,182,212,0.4)] hover:shadow-[0_0_25px_rgba(6,182,212,0.6)] transition-all">
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                {t.download}
                             </a>
                           )}
                         </div>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { ImageFormat, ProcessOptions, Language, RawPixelFormat, WatermarkPosition } from '../types';

interface ControlsProps {
  options: ProcessOptions;
  setOptions: React.Dispatch<React.SetStateAction<ProcessOptions>>;
  onProcess: () => void;
  isProcessing: boolean;
  originalDimensions?: { width: number; height: number };
  lang: Language;
  inputFormat?: string; 
}

export const Controls: React.FC<ControlsProps> = ({ 
  options, 
  setOptions, 
  onProcess, 
  isProcessing,
  originalDimensions,
  lang,
  inputFormat
}) => {
  const t = {
    en: {
      settings: "SYSTEM_CONFIG",
      sourceSettings: "RAW_DATA_INPUT",
      sourceDesc: "Required: Specify format & dimensions.",
      format: "OUTPUT_FORMAT",
      pixelFormat: "PIXEL_FORMAT",
      quality: "COMPRESSION",
      resize: "DIMENSIONS",
      maintainAspect: "LOCK_ASPECT",
      transform: "TRANSFORM",
      filters: "FILTERS",
      grayscale: "GRAYSCALE",
      sharpen: "SHARPEN",
      blur: "GAUSSIAN_BLUR",
      watermark: "WATERMARK",
      watermarkPos: "POSITION",
      posTL: "Top Left",
      posTR: "Top Right",
      posC: "Center",
      posBL: "Bottom Left",
      posBR: "Bottom Right",
      processBtn: "EXECUTE PROCESS",
      processing: "PROCESSING...",
      rotBtn: "ROT +90°",
      flipH: "FLIP H",
      flipV: "FLIP V",
      widthLabel: "W",
      heightLabel: "H"
    },
    zh: {
      settings: "系统配置",
      sourceSettings: "RAW 数据源",
      sourceDesc: "必填：指定格式与尺寸",
      format: "输出格式",
      pixelFormat: "像素格式",
      quality: "压缩质量",
      resize: "尺寸调整",
      maintainAspect: "锁定比例",
      transform: "变换控制",
      filters: "图像滤镜",
      grayscale: "灰度模式",
      sharpen: "锐化增强",
      blur: "高斯模糊",
      watermark: "水印叠加",
      watermarkPos: "位置",
      posTL: "左上",
      posTR: "右上",
      posC: "居中",
      posBL: "左下",
      posBR: "右下",
      processBtn: "执行处理",
      processing: "处理中...",
      rotBtn: "旋转 +90°",
      flipH: "水平翻转",
      flipV: "垂直翻转",
      widthLabel: "宽",
      heightLabel: "高"
    }
  }[lang];

  const updateOption = <K extends keyof ProcessOptions>(key: K, value: ProcessOptions[K]) => {
    setOptions(prev => ({ ...prev, [key]: value }));
  };

  const handleDimensionChange = (dimension: 'width' | 'height', value: string) => {
    const numValue = value ? Number(value) : null;

    setOptions(prev => {
      const next = { ...prev, [dimension]: numValue };
      if (
        prev.maintainAspectRatio && 
        originalDimensions && 
        originalDimensions.width > 0 && 
        originalDimensions.height > 0 && 
        numValue !== null
      ) {
        const ratio = originalDimensions.width / originalDimensions.height;
        if (dimension === 'width') {
          next.height = Math.round(numValue / ratio);
        } else {
          next.width = Math.round(numValue * ratio);
        }
      }
      return next;
    });
  };

  const handleAspectToggle = (checked: boolean) => {
    setOptions(prev => {
      const next = { ...prev, maintainAspectRatio: checked };
      if (
        checked && 
        originalDimensions && 
        originalDimensions.width > 0 && 
        originalDimensions.height > 0 && 
        next.width
      ) {
         const ratio = originalDimensions.width / originalDimensions.height;
         next.height = Math.round(next.width / ratio);
      }
      return next;
    });
  };

  const isRaw = inputFormat && (
      ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'].some(ext => inputFormat.toLowerCase().endsWith(ext))
  );

  const rotateCount = (options.rotate % 360) / 90;

  return (
    <>
      <div className="bg-slate-900/80 backdrop-blur-md rounded-none border border-cyan-900/50 flex flex-col h-full overflow-hidden relative">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-600 to-transparent"></div>

        <div className="p-4 border-b border-cyan-900/30 bg-slate-900/50 flex justify-between items-center">
          <h2 className="font-tech font-bold text-cyan-400 tracking-wider flex items-center">
            <span className="w-2 h-2 bg-cyan-500 mr-3 animate-pulse"></span>
            {t.settings}
          </h2>
          <div className="flex gap-1">
             <div className="w-1 h-1 bg-slate-600"></div>
             <div className="w-1 h-1 bg-slate-600"></div>
             <div className="w-1 h-1 bg-slate-600"></div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-5 space-y-8 custom-scrollbar">

          {isRaw && (
            <section className="bg-amber-900/20 p-4 border-l-2 border-amber-500">
               <label className="block text-xs font-bold text-amber-500 mb-1 font-tech tracking-wider">{t.sourceSettings}</label>
               <p className="text-[10px] text-amber-400/70 mb-4 font-code">{t.sourceDesc}</p>
               <div className="mb-4">
                 <label className="block text-[10px] font-semibold text-slate-400 mb-1 font-code">{t.pixelFormat}</label>
                 <select
                   value={options.rawPixelFormat || 'uyvy'}
                   onChange={(e) => updateOption('rawPixelFormat', e.target.value as RawPixelFormat)}
                   className="w-full bg-black/40 border border-amber-500/30 text-amber-100 text-xs py-2 px-3 focus:outline-none focus:border-amber-500 font-code uppercase"
                 >
                   <option value="uyvy">UYVY (YUV 4:2:2)</option>
                   <option value="nv21">NV21 (YUV 4:2:0)</option>
                   <option value="rgba">RGBA (32-bit)</option>
                   <option value="bgra">BGRA (32-bit)</option>
                   <option value="rgb">RGB (24-bit)</option>
                   <option value="bgr">BGR (24-bit)</option>
                 </select>
               </div>
               <div className="flex gap-2 items-center">
                  <div className="relative w-full">
                    <input type="number" placeholder="W" value={options.rawWidth || ''} onChange={(e) => updateOption('rawWidth', e.target.value ? Number(e.target.value) : undefined)} className="w-full bg-black/40 border border-amber-500/30 text-amber-100 text-xs py-2 px-3 pl-3 pr-8 focus:outline-none focus:border-amber-500 font-code" />
                    <span className="absolute right-3 top-2 text-[10px] text-slate-500">px</span>
                  </div>
                  <span className="text-slate-600">×</span>
                  <div className="relative w-full">
                    <input type="number" placeholder="H" value={options.rawHeight || ''} onChange={(e) => updateOption('rawHeight', e.target.value ? Number(e.target.value) : undefined)} className="w-full bg-black/40 border border-amber-500/30 text-amber-100 text-xs py-2 px-3 pl-3 pr-8 focus:outline-none focus:border-amber-500 font-code" />
                    <span className="absolute right-3 top-2 text-[10px] text-slate-500">px</span>
                  </div>
                </div>
            </section>
          )}

          <section>
            <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.format}</label>
            <div className="grid grid-cols-3 gap-2">
              {[ImageFormat.ORIGINAL, ImageFormat.JPEG, ImageFormat.PNG, ImageFormat.WEBP, ImageFormat.BMP].map(fmt => (
                <button key={fmt} onClick={() => updateOption('format', fmt)} className={`px-2 py-2 text-[10px] border font-code uppercase transition-all ${options.format === fmt ? 'bg-cyan-500/20 border-cyan-400 text-cyan-300 shadow-[0_0_10px_rgba(6,182,212,0.2)]' : 'bg-transparent border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}>{fmt === 'original' ? 'ORIG' : fmt}</button>
              ))}
            </div>
          </section>

          {options.format !== ImageFormat.PNG && options.format !== ImageFormat.BMP && (
            <section>
              <div className="flex justify-between mb-2">
                <label className="text-xs font-bold text-cyan-500 font-tech tracking-wider uppercase">{t.quality}</label>
                <span className="text-xs font-code text-cyan-300">{options.quality}%</span>
              </div>
              <input type="range" min="10" max="100" value={options.quality} onChange={(e) => updateOption('quality', Number(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500" />
            </section>
          )}

          <section>
            <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.resize}</label>
            <div className="flex gap-2 items-center mb-3">
              <div className="relative w-full">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-500 font-bold">{t.widthLabel}</span>
                <input type="number" placeholder={originalDimensions?.width ? originalDimensions.width.toString() : ''} value={options.width || ''} onChange={(e) => handleDimensionChange('width', e.target.value)} className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 pl-8 pr-3 focus:outline-none focus:border-cyan-500 font-code placeholder-slate-700" />
              </div>
              <span className="text-slate-600 text-xs">×</span>
              <div className="relative w-full">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-500 font-bold">{t.heightLabel}</span>
                <input type="number" placeholder={originalDimensions?.height ? originalDimensions.height.toString() : ''} value={options.height || ''} onChange={(e) => handleDimensionChange('height', e.target.value)} className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 pl-8 pr-3 focus:outline-none focus:border-cyan-500 font-code placeholder-slate-700" />
              </div>
            </div>
            <div className="flex items-center">
              <input type="checkbox" id="aspect" checked={options.maintainAspectRatio} onChange={(e) => handleAspectToggle(e.target.checked)} className="h-3 w-3 text-cyan-600 bg-black border-slate-600 rounded focus:ring-cyan-500 focus:ring-offset-0" />
              <label htmlFor="aspect" className="ml-2 text-xs text-slate-400 font-code">{t.maintainAspect}</label>
            </div>
          </section>

          <section>
            <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.transform}</label>
            <div className="mb-2">
               <button onClick={() => updateOption('rotate', (options.rotate + 90) % 360)} className={`w-full py-1.5 border font-code text-[10px] transition-all relative overflow-hidden group ${rotateCount > 0 ? 'bg-cyan-900/40 border-cyan-500 text-cyan-400 shadow-[0_0_10px_rgba(6,182,212,0.2)]' : 'bg-black/20 border-slate-700 text-slate-400 hover:text-cyan-300 hover:border-cyan-500/50'}`}>
                 <span className="relative z-10 flex items-center justify-center gap-2">{t.rotBtn} {rotateCount > 0 && (<span className="bg-cyan-500 text-black px-1.5 py-0.5 rounded-sm font-bold text-[9px] shadow-sm">x{rotateCount}</span>)}</span>
                 {rotateCount > 0 && <div className="absolute inset-0 bg-cyan-400/5 animate-pulse z-0"></div>}
               </button>
            </div>
            <div className="flex gap-2">
              <button onClick={() => updateOption('flipX', !options.flipX)} className={`flex-1 py-1.5 border text-[10px] font-code transition-colors ${options.flipX ? 'bg-cyan-900/40 border-cyan-500 text-cyan-400' : 'border-slate-700 bg-black/20 text-slate-400 hover:text-cyan-300 hover:border-cyan-500/50'}`}>{t.flipH}</button>
              <button onClick={() => updateOption('flipY', !options.flipY)} className={`flex-1 py-1.5 border text-[10px] font-code transition-colors ${options.flipY ? 'bg-cyan-900/40 border-cyan-500 text-cyan-400' : 'border-slate-700 bg-black/20 text-slate-400 hover:text-cyan-300 hover:border-cyan-500/50'}`}>{t.flipV}</button>
            </div>
          </section>

          <section>
             <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.filters}</label>
             <div className="space-y-3">
               <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                  <span className="text-xs text-slate-400 font-code">{t.grayscale}</span>
                  <input type="checkbox" checked={options.grayscale} onChange={(e) => updateOption('grayscale', e.target.checked)} className="h-3 w-3 text-cyan-600 bg-black border-slate-600 rounded focus:ring-cyan-500 focus:ring-offset-0" />
               </div>
               <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                  <span className="text-xs text-slate-400 font-code">{t.sharpen}</span>
                  <input type="checkbox" checked={options.sharpen} onChange={(e) => updateOption('sharpen', e.target.checked)} className="h-3 w-3 text-cyan-600 bg-black border-slate-600 rounded focus:ring-cyan-500 focus:ring-offset-0" />
               </div>
               <div>
                  <div className="flex justify-between mb-1">
                    <span className="text-xs text-slate-400 font-code">{t.blur}</span>
                    <span className="text-[10px] text-cyan-500 font-code">{options.blur}px</span>
                  </div>
                  <input type="range" min="0" max="20" step="0.5" value={options.blur} onChange={(e) => updateOption('blur', Number(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500" />
               </div>
             </div>
          </section>

          <section>
             <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.watermark}</label>
             <div className="mb-2">
               <label className="block text-[10px] text-slate-500 mb-1 font-code">{t.watermarkPos}</label>
               <select value={options.watermarkPosition || 'bottom-right'} onChange={(e) => updateOption('watermarkPosition', e.target.value as WatermarkPosition)} className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 px-3 focus:outline-none focus:border-cyan-500 font-code uppercase">
                 <option value="top-left">{t.posTL}</option>
                 <option value="top-right">{t.posTR}</option>
                 <option value="center">{t.posC}</option>
                 <option value="bottom-left">{t.posBL}</option>
                 <option value="bottom-right">{t.posBR}</option>
               </select>
             </div>
             <textarea rows={2} placeholder="" value={options.watermarkText} onChange={(e) => updateOption('watermarkText', e.target.value)} className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 px-3 focus:outline-none focus:border-cyan-500 font-code rounded-sm" />
          </section>
        </div>

        <div className="p-4 border-t border-cyan-900/30 bg-slate-900/50 relative">
          <button
            onClick={onProcess}
            disabled={isProcessing}
            className={`w-full py-3 px-4 font-tech font-bold uppercase tracking-widest text-sm clip-button transition-all relative overflow-hidden group
              ${isProcessing 
                ? 'bg-slate-700 text-slate-400 cursor-not-allowed' 
                : 'bg-cyan-600 hover:bg-cyan-500 text-white shadow-[0_0_20px_rgba(6,182,212,0.4)] hover:shadow-[0_0_30px_rgba(6,182,212,0.6)]'
              }
            `}
          >
            <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
            {isProcessing ? t.processing : t.processBtn}
          </button>
        </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Dropzone } from './components/Dropzone';
import { Controls } from './components/Controls';
import { StockDashboard } from './components/StockDashboard';
import { AICore } from './components/AICore';
import { ImageFormat, ProcessOptions, UploadResponse, ProcessResponse, Language, RawPixelFormat } from './types';

const defaultOptions: ProcessOptions = {
  format: ImageFormat.ORIGINAL,
  quality: 85,
  width: null,
  height: null,
  maintainAspectRatio: true,
  resizeMode: 'cover',
  rotate: 0,
  flipX: false,
  flipY: false,
  grayscale: false,
  blur: 0,
  sharpen: false,
  watermarkText: '',
  watermarkPosition: 'bottom-right',
  rawWidth: undefined,
  rawHeight: undefined,
  rawPixelFormat: 'uyvy',
  aiTask: 'vision',
  aiPrompt: ''
};

type AppMode = 'image' | 'data' | 'ai';

function App() {
  const [lang, setLang] = useState<Language>('en');
  const [mode, setMode] = useState<AppMode>('image');

  // Security States
  const [dataUnlocked, setDataUnlocked] = useState(false);
  const [aiUnlocked, setAiUnlocked] = useState(false); // Added AI Lock
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordInput, setPasswordInput] = useState('');
  const [unlockTarget, setUnlockTarget] = useState<'data' | 'ai' | null>(null); // Track what we are unlocking

  // Image Core States
  const [currentFile, setCurrentFile] = useState<UploadResponse | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [options, setOptions] = useState<ProcessOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessResponse | null>(null);
  const [error, setError] = useState<string | null>(null); // New Error State
  const [totalProcessed, setTotalProcessed] = useState(0);

  const t = {
    en: {
      appTitle: "TUKUKU",
      sloganTitle: "IMAGE PROCESSOR",
      uploadFailed: "CRITICAL ERROR: UPLOAD FAILED",
      processFailed: "PROCESSING ERROR",
      processedSuccess: "RENDER_COMPLETE",
      preview: "VISUAL_FEED",
      noPreview: "NO VISUAL FEED FOR RAW DATA",
      originalSize: "INPUT_SIZE",
      newSize: "OUTPUT_SIZE",
      savings: "EFFICIENCY",
      startOver: "RESET_SYSTEM",
      download: "EXTRACT_DATA",
      serverDesc: "SECURE SERVER CONNECTION :: ESTABLISHED",
      status: "STATUS",
      coord: "COORD",
      auto: "AUTO",
      modeImage: "IMAGE_CORE",
      modeData: "DATA_CORE",
      modeAI: "AI_CORE",
      enterPwd: "ENTER ACCESS CODE",
      unlock: "UNLOCK",
      accessDenied: "ACCESS DENIED: INVALID TOKEN",
      aiResult: "NEURAL ANALYSIS",
      error: "SYSTEM ALERT"
    },
    zh: {
      appTitle: "图酷酷",
      sloganTitle: "图像处理器",
      uploadFailed: "严重错误：上传失败",
      processFailed: "处理错误",
      processedSuccess: "渲染完毕",
      preview: "视觉反馈",
      noPreview: "RAW 数据无视觉反馈",
      originalSize: "输入体积",
      newSize: "输出体积",
      savings: "效率提升",
      startOver: "重置系统",
      download: "提取数据",
      serverDesc: "安全连接 :: 已建立",
      status: "状态",
      coord: "尺寸",
      auto: "自动",
      modeImage: "图像核心",
      modeData: "数据核心",
      modeAI: "AI 核心",
      enterPwd: "输入访问密钥",
      unlock: "解锁",
      accessDenied: "访问拒绝：无效的密钥",
      aiResult: "神经分析结果",
      error: "系统警报"
    }
  }[lang];

  useEffect(() => {
    fetch('/api/stats')
      .then(res => res.json())
      .then(data => {
        if (data.processedCount) setTotalProcessed(data.processedCount);
      })
      .catch(err => console.error("Failed to load stats", err));
  }, []);

  const getFormatFromExt = (filename: string): RawPixelFormat => {
      const lower = filename.toLowerCase();
      if (lower.endsWith('.uyvy')) return 'uyvy';
      if (lower.endsWith('.nv21')) return 'nv21';
      if (lower.endsWith('.rgba')) return 'rgba';
      if (lower.endsWith('.bgra')) return 'bgra';
      if (lower.endsWith('.rgb')) return 'rgb';
      if (lower.endsWith('.bgr')) return 'bgr';
      return 'uyvy'; 
  };

  const isRawFormat = (filename: string) => {
      const exts = ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'];
      return exts.some(ext => filename.toLowerCase().endsWith(ext));
  };

  const handleFileUpload = async (file: File) => {
    setIsUploading(true);
    setResult(null);
    setError(null);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        let errorMessage = `${t.uploadFailed} (${response.status})`;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
          errorMessage = `${t.uploadFailed}: ${response.statusText || response.status}`;
        }
        throw new Error(errorMessage);
      }

      const data: UploadResponse = await response.json();
      setCurrentFile(data);

      const suggestedFormat = getFormatFromExt(data.originalName);
      const isRaw = isRawFormat(data.originalName);

      setOptions({
        ...defaultOptions,
        format: ImageFormat.ORIGINAL,
        width: data.width || null,
        height: data.height || null,
        rawWidth: isRaw ? (data.width || 1920) : undefined,
        rawHeight: isRaw ? (data.height || 1080) : undefined,
        rawPixelFormat: suggestedFormat
      });
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.uploadFailed);
    } finally {
      setIsUploading(false);
    }
  };

  const handleProcess = async () => {
    if (!currentFile) return;

    setIsProcessing(true);
    setError(null);
    try {
      const response = await fetch('/api/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          options
        })
      });

      if (!response.ok) {
        let errorMessage = t.processFailed;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
           errorMessage = `${t.processFailed}: ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const data: ProcessResponse = await response.json();

      await new Promise((resolve) => {
        const img = new Image();
        if (data.url) {
            img.src = data.url;
            img.onload = resolve;
            img.onerror = resolve; 
        } else {
            resolve(true);
        }
      });

      setResult(data);
      setTotalProcessed(prev => prev + 1);

    } catch (error: any) {
      console.error(error);
      alert(error.message || t.processFailed);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleReset = () => {
    setCurrentFile(null);
    setResult(null);
    setError(null);
    setOptions(defaultOptions);
  };

  const getBitDepthLabel = (depth?: string) => {
    if (!depth) return null;
    if (depth === 'uchar') return null; 
    if (depth === 'ushort' || depth === 'short') return '16-BIT';
    if (depth === 'float') return '32-BIT FLOAT';
    if (depth === 'uint' || depth === 'int') return '32-BIT INT';
    return depth.toUpperCase();
  };

  const toggleLang = () => {
    setLang(prev => prev === 'en' ? 'zh' : 'en');
  };

  const handleModeSwitch = (newMode: AppMode) => {
    if (newMode === 'data' && !dataUnlocked) {
      setUnlockTarget('data');
      setShowPasswordModal(true);
    } else if (newMode === 'ai' && !aiUnlocked) {
      setUnlockTarget('ai');
      setShowPasswordModal(true);
    } else {
      setMode(newMode);
    }
  };

  const handleUnlock = () => {
    if (unlockTarget === 'data' && passwordInput === '666888') {
      setDataUnlocked(true);
      setShowPasswordModal(false);
      setMode('data');
      setPasswordInput('');
    } else if (unlockTarget === 'ai' && passwordInput === '666666') {
      setAiUnlocked(true);
      setShowPasswordModal(false);
      setMode('ai');
      setPasswordInput('');
    } else {
      alert(t.accessDenied);
      setShowPasswordModal(false); // keep open? usually better to keep open for retry, but follow pattern
      setPasswordInput('');
    }
  };

  return (
    <div className="flex flex-col h-full bg-transparent text-slate-300 font-sans selection:bg-cyan-500/30 selection:text-cyan-100">
      {/* Password Modal */}
      {showPasswordModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
           <div className={`bg-slate-900 border p-8 max-w-sm w-full shadow-[0_0_50px_rgba(0,0,0,0.5)] relative overflow-hidden ${unlockTarget === 'ai' ? 'border-emerald-500/50 shadow-[0_0_50px_rgba(16,185,129,0.3)]' : 'border-cyan-500/50 shadow-[0_0_50px_rgba(6,182,212,0.3)]'}`}>
               <div className={`absolute top-0 left-0 w-full h-1 bg-gradient-to-r animate-pulse ${unlockTarget === 'ai' ? 'from-emerald-500 via-green-500 to-emerald-500' : 'from-cyan-500 via-purple-500 to-cyan-500'}`}></div>
               <h3 className={`text-xl font-tech mb-6 text-center tracking-widest ${unlockTarget === 'ai' ? 'text-emerald-400' : 'text-cyan-400'}`}>{t.enterPwd}</h3>
               <input 
                 type="password" 
                 value={passwordInput}
                 onChange={(e) => setPasswordInput(e.target.value)}
                 className="w-full bg-black border border-slate-600 text-white px-4 py-2 font-code text-center tracking-[0.5em] mb-6 focus:outline-none focus:border-cyan-500"
                 autoFocus
                 onKeyDown={(e) => e.key === 'Enter' && handleUnlock()}
               />
               <div className="flex gap-4">
                  <button onClick={() => { setShowPasswordModal(false); setUnlockTarget(null); }} className="flex-1 py-2 font-code text-slate-500 hover:text-white border border-transparent hover:border-slate-500">CANCEL</button>
                  <button onClick={handleUnlock} className={`flex-1 py-2 text-white font-tech tracking-wider clip-button ${unlockTarget === 'ai' ? 'bg-emerald-600 hover:bg-emerald-500' : 'bg-cyan-600 hover:bg-cyan-500'}`}>{t.unlock}</button>
               </div>
           </div>
        </div>
      )}

      {/* Header */}
      <header className="border-b border-cyan-900/50 bg-[#020617]/90 backdrop-blur-md py-4 px-6 shadow-[0_0_20px_rgba(6,182,212,0.1)] relative z-20">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={handleReset}>
            <div className={`w-10 h-10 border rounded-none flex items-center justify-center relative overflow-hidden transition-all duration-300 ${mode === 'image' ? 'bg-cyan-900/30 border-cyan-500' : mode === 'data' ? 'bg-purple-900/30 border-purple-500' : 'bg-emerald-900/30 border-emerald-500'}`}>
               <div className={`absolute inset-0 animate-pulse ${mode === 'image' ? 'bg-cyan-400/10' : mode === 'data' ? 'bg-purple-400/10' : 'bg-emerald-400/10'}`}></div>
               {mode === 'image' && (
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-cyan-400 relative z-10"><path strokeLinecap="square" strokeLinejoin="miter" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456zM16.894 20.567L16.5 21.75l-.394-1.183a2.25 2.25 0 00-1.423-1.423L13.5 18.75l1.183-.394a2.25 2.25 0 001.423-1.423l.394-1.183.394 1.183a2.25 2.25 0 001.423 1.423l1.183.394-1.183.394a2.25 2.25 0 00-1.423 1.423z" /></svg>
               )}
               {mode === 'data' && (
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-purple-400 relative z-10"><path strokeLinecap="square" strokeLinejoin="miter" d="M3.75 6A2.25 2.25 0 016 3.75h2.25A2.25 2.25 0 0110.5 6v2.25a2.25 2.25 0 01-2.25 2.25H6a2.25 2.25 0 01-2.25-2.25V6zM3.75 15.75A2.25 2.25 0 016 13.5h2.25a2.25 2.25 0 012.25 2.25V18a2.25 2.25 0 01-2.25 2.25H6A2.25 2.25 0 013.75 18v-2.25zM13.5 6a2.25 2.25 0 012.25-2.25H18A2.25 2.25 0 0120.25 6v2.25A2.25 2.25 0 0118 10.5h-2.25a2.25 2.25 0 01-2.25-2.25V6zM13.5 15.75a2.25 2.25 0 012.25-2.25H18a2.25 2.25 0 012.25 2.25V18A2.25 2.25 0 0118 20.25h-2.25A2.25 2.25 0 0113.5 18v-2.25z" /></svg>
               )}
               {mode === 'ai' && (
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-emerald-400 relative z-10"><path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
               )}
            </div>
            <div>
              <h1 className="text-2xl font-tech font-bold tracking-widest text-cyan-50 hover-glitch" data-text={t.appTitle}>{t.appTitle}</h1>
              <div className={`h-0.5 w-full bg-gradient-to-r to-transparent transition-colors duration-500 ${mode === 'image' ? 'from-cyan-500' : mode === 'data' ? 'from-purple-500' : 'from-emerald-500'}`}></div>
            </div>
          </div>

          <div className="hidden md:flex bg-slate-900 border border-slate-700 p-1 rounded-sm">
             <button onClick={() => handleModeSwitch('ai')} className={`px-4 py-1 text-xs font-tech tracking-wider transition-all ${mode === 'ai' ? 'bg-emerald-600 text-white shadow-[0_0_10px_rgba(16,185,129,0.5)]' : 'text-slate-500 hover:text-slate-300'}`}>{t.modeAI}</button>
             <button onClick={() => handleModeSwitch('image')} className={`px-4 py-1 text-xs font-tech tracking-wider transition-all ${mode === 'image' ? 'bg-cyan-600 text-white shadow-[0_0_10px_rgba(6,182,212,0.5)]' : 'text-slate-500 hover:text-slate-300'}`}>{t.modeImage}</button>
             <button onClick={() => handleModeSwitch('data')} className={`px-4 py-1 text-xs font-tech tracking-wider transition-all ${mode === 'data' ? 'bg-purple-600 text-white shadow-[0_0_10px_rgba(168,85,247,0.5)]' : 'text-slate-500 hover:text-slate-300'}`}>{t.modeData}</button>
          </div>

          <div className="flex items-center gap-6">
             <button onClick={toggleLang} className="flex items-center justify-center px-4 py-1.5 text-xs font-code font-bold text-cyan-400 border border-cyan-800 hover:bg-cyan-900/30 hover:border-cyan-500 transition-all uppercase tracking-wider">[{lang === 'en' ? 'CN' : 'EN'}]</button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden relative z-10">
        <div className="absolute inset-0 overflow-y-auto custom-scrollbar">

          {mode === 'data' ? (
             <div className="max-w-7xl mx-auto h-full min-h-[calc(100vh-80px)]"><StockDashboard lang={lang} /></div>
          ) : mode === 'ai' ? (
             <div className="h-full min-h-[calc(100vh-80px)] bg-[#020617]"><AICore lang={lang} /></div>
          ) : (
            <div className="max-w-7xl mx-auto p-6 h-full min-h-[calc(100vh-80px)]">
              {!currentFile ? (
                <div className="h-full flex flex-col justify-center items-center max-w-3xl mx-auto mt-20 md:mt-0">
                  <div className="w-full text-center mb-12 relative">
                     <h2 className="text-5xl md:text-6xl font-tech font-black text-transparent bg-clip-text bg-gradient-to-b from-white to-slate-500 mb-6 tracking-tighter drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]">{t.sloganTitle}</h2>
                  </div>
                  <div className="w-full max-w-xl"><Dropzone onFileSelect={handleFileUpload} isUploading={isUploading} lang={lang} processedCount={totalProcessed} /></div>
                </div>
              ) : (
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full pb-10">
                  <div className="lg:col-span-4 h-full max-h-[850px]">
                    <Controls 
                      options={options} 
                      setOptions={setOptions} 
                      onProcess={handleProcess}
                      isProcessing={isProcessing}
                      originalDimensions={{ width: currentFile.width || 0, height: currentFile.height || 0 }}
                      lang={lang}
                      inputFormat={currentFile.originalName} 
                    />
                  </div>

                  <div className="lg:col-span-8 flex flex-col gap-6">
                    <div className="bg-slate-900/50 border border-slate-700 rounded-none flex-1 flex flex-col relative overflow-hidden group h-[500px] lg:h-auto">
                      <div className="absolute top-0 left-0 p-2 z-20 flex gap-1">
                          <div className="w-16 h-1 bg-cyan-600/50"></div>
                          <div className="w-4 h-1 bg-cyan-600/50"></div>
                      </div>
                      <div className="absolute bottom-0 right-0 p-2 z-20 text-[10px] font-code text-slate-500 uppercase">{t.coord}: {options.width || t.auto} x {options.height || t.auto}</div>

                      <div className="relative z-10 w-full h-full flex items-center justify-center p-8 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
                        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-cyan-900/5 to-transparent pointer-events-none"></div>

                        {isProcessing && (
                           <div className="absolute inset-0 z-30 pointer-events-none"><div className="scanner-overlay"></div><div className="scanner-line"></div></div>
                        )}

                        {error && (
                            <div className="absolute inset-0 z-50 flex items-center justify-center p-8 bg-black/80 backdrop-blur-md">
                                <div className="border border-rose-500 bg-rose-950/30 p-8 max-w-lg text-center shadow-[0_0_30px_rgba(244,63,94,0.3)]">
                                    <h3 className="text-xl font-tech text-rose-500 uppercase tracking-widest mb-4 animate-pulse">{t.error}</h3>
                                    <p className="text-white font-code text-sm leading-relaxed">{error}</p>
                                </div>
                            </div>
                        )}

                        {result && !error ? (
                           <div className="flex flex-col items-center relative w-full h-full justify-center">
                              {/* --- AI TEXT RESULT --- */}
                              {result.aiText && (
                                <div className="absolute inset-0 z-40 bg-black/80 backdrop-blur-md p-8 overflow-y-auto">
                                   <h3 className="text-purple-400 font-tech uppercase tracking-widest mb-4 border-b border-purple-500/30 pb-2">{t.aiResult}</h3>
                                   <p className="text-white font-code text-sm leading-relaxed whitespace-pre-wrap">{result.aiText}</p>
                                </div>
                              )}

                              {/* --- VIDEO RESULT --- */}
                              {result.mimeType === 'video/mp4' ? (
                                <video controls autoPlay loop className="max-h-[500px] w-full shadow-[0_0_30px_rgba(168,85,247,0.3)] border border-purple-500">
                                   <source src={result.url} type="video/mp4" />
                                   Your browser does not support the video tag.
                                </video>
                              ) : (
                                /* --- IMAGE RESULT --- */
                                <img 
                                  src={result.url} 
                                  alt="Processed" 
                                  className="max-h-[500px] w-full object-contain shadow-[0_0_30px_rgba(6,182,212,0.15)] border border-slate-700" 
                                />
                              )}

                              <div className="absolute top-4 right-4 z-40 pointer-events-none">
                                  <div className="flex items-center gap-3 bg-cyan-950/80 border-l-2 border-cyan-400 px-4 py-2 backdrop-blur-md shadow-[0_0_15px_rgba(6,182,212,0.2)] animate-pulse">
                                      <div className="flex flex-col items-end">
                                          <span className="text-[10px] font-tech text-cyan-400 tracking-widest">{t.status}</span>
                                          <span className="text-sm font-code font-bold text-white tracking-wider">{t.processedSuccess}</span>
                                      </div>
                                      <div className="w-2 h-2 bg-cyan-400 shadow-[0_0_10px_#06b6d4] rounded-full"></div>
                                  </div>
                              </div>
                           </div>
                        ) : !error && (
                          <div className="relative w-full h-full flex items-center justify-center">
                             {isRawFormat(currentFile.filename) ? (
                                <div className="flex flex-col items-center justify-center p-8 border border-slate-700 bg-slate-900/80 backdrop-blur-sm relative z-20">
                                   <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-16 h-16 text-yellow-600 mb-4 opacity-80"><path strokeLinecap="square" strokeLinejoin="miter" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m0 12.75h7.5m-7.5 3H12M10.5 2.25H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" /></svg>
                                   <span className="text-yellow-500 font-tech tracking-wider text-lg animate-pulse">{t.noPreview}</span>
                                   <span className="text-yellow-700 font-code text-xs mt-2 text-center max-w-xs uppercase border-t border-yellow-800/50 pt-2">{lang === 'en' ? 'Awaiting parameter configuration...' : '等待参数配置...'}</span>
                                </div>
                             ) : (
                               <>
                                 <img 
                                   src={currentFile.url} 
                                   alt="Original" 
                                   decoding="async"
                                   className="max-h-[500px] object-contain shadow-2xl border border-slate-700 transition-all duration-300 z-20" 
                                   style={{
                                     transform: `rotate(${options.rotate}deg) scaleX(${options.flipX ? -1 : 1}) scaleY(${options.flipY ? -1 : 1})`,
                                     filter: `grayscale(${options.grayscale ? 1 : 0}) blur(${options.blur}px) ${options.sharpen ? 'contrast(1.2) brightness(1.1)' : ''}`
                                   }} 
                                 />
                                 <div className="absolute top-4 right-4 bg-black/70 border border-cyan-500/30 text-cyan-400 text-[10px] font-code px-3 py-1 backdrop-blur-md uppercase tracking-widest z-20">● {t.preview}</div>
                               </>
                             )}
                          </div>
                        )}
                      </div>
                    </div>

                    {result && !error && (
                      <div className="bg-slate-900/80 border-t border-b border-cyan-900/50 p-4 flex items-center justify-between relative backdrop-blur-md">
                         <div className="absolute top-0 left-0 w-1 h-full bg-cyan-500"></div>

                         <div className="flex items-center gap-8">
                            <div className="text-xs font-code">
                               <p className="text-slate-500 uppercase tracking-wider mb-1">{t.originalSize}</p>
                               <p className="text-slate-200">{formatSize(currentFile.size)} {getBitDepthLabel(currentFile.depth) && (<span className="text-slate-600 ml-2">[{getBitDepthLabel(currentFile.depth)}]</span>)}</p>
                            </div>

                            <div className="text-2xl text-slate-700 font-thin">/</div>

                            {/* Only show output size if a file was actually generated (not just text) */}
                            {result.size && (
                              <>
                                <div className="text-xs font-code">
                                  <p className="text-slate-500 uppercase tracking-wider mb-1">{t.newSize}</p>
                                  <p className="text-cyan-400 font-bold glow-text">{formatSize(result.size)}</p>
                                </div>
                                <div className="text-2xl text-slate-700 font-thin">/</div>
                                <div className="text-xs font-code">
                                  <p className="text-slate-500 uppercase tracking-wider mb-1">{t.savings}</p>
                                  <p className="text-green-400">{currentFile.size > result.size ? Math.round(((currentFile.size - result.size) / currentFile.size) * 100) + '%' : 'N/A'}</p>
                                </div>
                              </>
                            )}
                         </div>

                         <div className="flex gap-4">
                           <button onClick={handleReset} className="px-4 py-2 text-xs font-code font-bold text-slate-400 hover:text-white border border-transparent hover:border-slate-500 transition-all uppercase tracking-wider">{t.startOver}</button>
                           {result.url && (
                             <a href={result.url} download={result.filename} className="flex items-center gap-2 bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-2 font-tech font-bold uppercase tracking-widest text-xs clip-button shadow-[0_0_15px_rgba(6,182,212,0.4)] hover:shadow-[0_0_25px_rgba(6,182,212,0.6)] transition-all">
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                {t.download}
                             </a>
                           )}
                         </div>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Language, ChatMessage, AIModelVersion, ChatSession, AIWorkMode, AIAttachment } from '../types';

interface AICoreProps {
  lang: Language;
}

export const AICore: React.FC<AICoreProps> = ({ lang }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [model, setModel] = useState<AIModelVersion>('gemini-3-flash-preview');

  // Attachments & Audio
  const [attachments, setAttachments] = useState<AIAttachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = {
    en: {
      aiCoreTitle: "AI_CORE",
      newChat: "NEW SESSION",
      placeholder: "Broadcast message to core...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      history: "SESSIONS",
      modes: "WORK MODE",
      modeGen: "GENERAL",
      modeCode: "ENGINEER",
      modeData: "ANALYST",
      modeCreate: "CREATIVE",
      upload: "UPLOAD FILE",
      voice: "VOICE",
      listening: "LISTENING...",
      attach: "ATTACHED RES:",
      play: "PLAY",
      tts: "READ ALOUD",
      emptyState: "AWAITING INPUT STREAM...",
      processing: "PROCESSING...",
      error: "Error: Neural Link Failed.",
      user: "U",
      ai: "AI"
    },
    zh: {
      aiCoreTitle: "AI 核心",
      newChat: "新建会话",
      placeholder: "输入指令或提问...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      history: "历史会话",
      modes: "工作模式",
      modeGen: "通用助手",
      modeCode: "赛博工程师",
      modeData: "数据分析师",
      modeCreate: "创意总监",
      upload: "上传文件",
      voice: "语音输入",
      listening: "正在聆听...",
      attach: "已挂载资源:",
      play: "播放",
      tts: "朗读",
      emptyState: "等待输入信号...",
      processing: "计算中...",
      error: "错误：神经连接中断。",
      user: "我",
      ai: "AI"
    }
  }[lang];

  const modeLabels: Record<string, string> = {
      general: t.modeGen,
      coder: t.modeCode,
      analyst: t.modeData,
      creative: t.modeCreate
  };

  // --- Session Management ---
  useEffect(() => {
    fetchSessions();
  }, []);

  const fetchSessions = async () => {
    try {
      const res = await fetch('/api/ai/sessions');
      const data = await res.json();
      setSessions(data);
      if (data.length > 0 && !currentSessionId) {
          // Don't auto-select to allow "Fresh Start", or select first
          // setCurrentSessionId(data[0].id);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const createSession = async (mode: AIWorkMode = 'general') => {
    const res = await fetch('/api/ai/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode })
    });
    const newSession = await res.json();
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    setMessages([]);
    setAttachments([]);
  };

  const deleteSession = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      await fetch(`/api/ai/sessions/${id}`, { method: 'DELETE' });
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
          setCurrentSessionId(null);
          setMessages([]);
      }
  };

  // --- Messaging ---
  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if ((!textToSend.trim() && attachments.length === 0) || isLoading) return;

    // Auto-create session if none
    let activeSessionId = currentSessionId;
    if (!activeSessionId) {
        // Quick session creation
        const res = await fetch('/api/ai/sessions', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'general' }) });
        const newS = await res.json();
        setSessions(prev => [newS, ...prev]);
        activeSessionId = newS.id;
        setCurrentSessionId(newS.id);
    }

    const tempAttachments = [...attachments];

    // User Message
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      timestamp: Date.now(),
      attachments: tempAttachments
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachments([]);
    setIsLoading(true);

    // AI Placeholder
    const aiMsgId = (Date.now() + 1).toString();
    const aiMsgPlaceholder: ChatMessage = {
      id: aiMsgId,
      role: 'model',
      text: '',
      timestamp: Date.now() + 1,
      isThinking: true
    };
    setMessages(prev => [...prev, aiMsgPlaceholder]);

    try {
      const response = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId: activeSessionId,
          message: textToSend,
          attachments: tempAttachments, // Send metadata + base64 if small
          model: model,
          lang: lang // Pass language setting
        })
      });

      if (!response.body) throw new Error("No response");

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let done = false;
      let accumulatedText = '';

      while (!done) {
        const { value, done: doneReading } = await reader.read();
        done = doneReading;
        const chunkValue = decoder.decode(value, { stream: !done });
        accumulatedText += chunkValue;

        setMessages(prev => prev.map(msg => 
          msg.id === aiMsgId 
            ? { ...msg, text: accumulatedText, isThinking: false } 
            : msg
        ));
      }

      // Update Session Preview in list locally
      setSessions(prev => prev.map(s => s.id === activeSessionId ? { ...s, lastMessageAt: Date.now(), preview: accumulatedText.substring(0, 50) } : s));

    } catch (error) {
      console.error(error);
      setMessages(prev => prev.map(msg => 
        msg.id === aiMsgId ? { ...msg, text: t.error, isThinking: false } : msg
      ));
    } finally {
      setIsLoading(false);
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  };

  // --- Attachments ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];
          const formData = new FormData();
          formData.append('image', file);

          try {
              const res = await fetch('/api/upload', { method: 'POST', body: formData });
              const data = await res.json();

              // For small text files/images, we can also read client side for preview
              // For now, we trust server response
              const newAtt: AIAttachment = {
                  id: data.id,
                  type: file.type.startsWith('image/') ? 'image' : 'file',
                  url: data.url,
                  filename: data.filename,
                  mimeType: data.mimeType || file.type
              };
              setAttachments(prev => [...prev, newAtt]);
          } catch (e) { console.error(e); alert("Upload Failed"); }
      }
  };

  // --- Voice Input (STT) ---
  const startRecording = async () => {
      try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          const mediaRecorder = new MediaRecorder(stream);
          mediaRecorderRef.current = mediaRecorder;
          const chunks: Blob[] = [];

          mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
          mediaRecorder.onstop = async () => {
              const blob = new Blob(chunks, { type: 'audio/webm' }); // Chrome uses webm
              const formData = new FormData();
              formData.append('audio', blob, 'voice_input.webm');

              setIsLoading(true); // Temp loading while transcribing
              try {
                  const res = await fetch('/api/ai/transcribe', { method: 'POST', headers: { 'api-key': 'internal' }, body: formData });
                  const data = await res.json();
                  if (data.text) {
                      handleSend(data.text); // Auto send transcript
                  }
              } catch (e) { console.error(e); } finally { setIsLoading(false); }
          };

          mediaRecorder.start();
          setIsRecording(true);
      } catch (e) { alert("Mic Access Denied"); }
  };

  const stopRecording = () => {
      mediaRecorderRef.current?.stop();
      setIsRecording(false);
  };

  // --- TTS ---
  const playTTS = async (text: string) => {
      try {
          // Strip Markdown images/video from TTS
          const cleanText = text.replace(/!\[.*?\]\(.*?\)/g, '');

          const res = await fetch('/api/ai/tts', { 
              method: 'POST', 
              headers: { 'Content-Type': 'application/json' }, 
              body: JSON.stringify({ text: cleanText }) 
          });
          const data = await res.json();
          if (data.audio) {
              const audio = new Audio(`data:audio/wav;base64,${data.audio}`);
              audio.play();
          }
      } catch (e) { console.error(e); }
  };

  // --- Message Renderer with Markdown Image/Video Support ---
  const renderMessageContent = (text: string) => {
      // Regex to find ![alt](url)
      const parts = text.split(/(!\[.*?\]\(.*?\))/g);
      return parts.map((part, index) => {
          const imgMatch = part.match(/!\[(.*?)\]\((.*?)\)/);
          if (imgMatch) {
              const alt = imgMatch[1];
              const url = imgMatch[2];

              // Handle MP4 Video
              if (url.endsWith('.mp4') || alt.toLowerCase().includes('video')) {
                   return (
                      <div key={index} className="my-2 rounded-lg overflow-hidden border border-purple-600 shadow-lg relative group">
                          <video src={url} controls className="w-full max-h-64 bg-black/50" />
                          <div className="bg-purple-900/50 p-1 text-[10px] text-purple-300 font-code text-center">GENERATED_VEO_ASSET</div>
                      </div>
                   );
              }

              return (
                  <div key={index} className="my-2 rounded-lg overflow-hidden border border-slate-600 shadow-lg">
                      <img src={url} alt={alt} className="w-full max-h-64 object-contain bg-black/20" />
                      <div className="bg-slate-900/50 p-1 text-[10px] text-slate-500 font-code text-center">GENERATED_ASSET</div>
                  </div>
              );
          }
          return <span key={index}>{part}</span>;
      });
  };

  // --- Render Helpers ---
  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  return (
    <div className="flex h-full bg-[#020617] text-slate-200 overflow-hidden font-sans relative">

      {/* --- SIDEBAR --- */}
      <div className="w-16 md:w-64 flex flex-col bg-slate-900/50 border-r border-cyan-900/30 backdrop-blur-md z-20 transition-all">
        <div className="p-4 flex flex-col gap-2">
          <button onClick={() => createSession('general')} className="w-full flex items-center justify-center md:justify-start gap-3 px-3 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-tech text-xs tracking-widest uppercase shadow-lg transition-all clip-button">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden md:inline">{t.newChat}</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
           <div className="hidden md:block text-[10px] text-slate-500 font-code uppercase tracking-widest mb-2 px-2">{t.history}</div>
           <div className="space-y-1">
             {sessions.map(s => (
               <div key={s.id} onClick={() => { setCurrentSessionId(s.id); setMessages([]); }} className={`group relative p-2 md:p-3 cursor-pointer border-l-2 transition-all ${currentSessionId === s.id ? 'bg-slate-800 border-cyan-500 text-cyan-100' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}>
                  <div className="flex justify-between items-center">
                      <div className="font-bold text-xs truncate w-full pr-6">{s.title || "Untitled Link"}</div>
                      <button onClick={(e) => deleteSession(s.id, e)} className="absolute right-2 opacity-0 group-hover:opacity-100 text-slate-600 hover:text-rose-500">×</button>
                  </div>
                  <div className="hidden md:block text-[10px] font-code truncate opacity-70 mt-1">{s.preview}</div>
                  <div className="hidden md:flex gap-2 mt-1">
                      <span className={`text-[8px] px-1 rounded border ${s.mode==='coder'?'border-purple-500 text-purple-400':s.mode==='analyst'?'border-emerald-500 text-emerald-400':'border-slate-600'}`}>{s.mode.toUpperCase()}</span>
                  </div>
               </div>
             ))}
           </div>
        </div>

        {/* Mode Selector (Quick Switch) */}
        <div className="p-2 border-t border-slate-800 hidden md:block">
            <div className="text-[10px] text-slate-500 font-code mb-2">{t.modes}</div>
            <div className="grid grid-cols-2 gap-1">
                {(['general', 'coder', 'analyst', 'creative'] as AIWorkMode[]).map(m => (
                    <button key={m} onClick={() => createSession(m)} className="text-[9px] border border-slate-700 p-1 hover:border-cyan-500 hover:text-cyan-400 uppercase transition-colors">
                        {modeLabels[m]} 
                    </button>
                ))}
            </div>
        </div>
      </div>

      {/* --- MAIN CHAT AREA --- */}
      <div className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

        {/* Header */}
        <div className="h-14 border-b border-cyan-900/30 bg-slate-900/80 backdrop-blur-md flex items-center justify-between px-6 z-30">
           <div className="flex items-center gap-2">
              <span className="text-cyan-400 font-tech text-lg">{t.aiCoreTitle}</span>
              <span className="text-slate-600 font-thin">/</span>
              <select value={model} onChange={(e) => setModel(e.target.value as AIModelVersion)} className="bg-transparent text-xs font-code text-slate-300 focus:outline-none uppercase cursor-pointer hover:text-cyan-400">
                 <option value="gemini-3-flash-preview">{t.modelFlash}</option>
                 <option value="gemini-3-pro-preview">{t.modelPro}</option>
              </select>
           </div>
           <div className="flex gap-4">
              {currentSessionId && <span className="text-xs font-code text-slate-500 uppercase border px-2 py-0.5 border-slate-700 rounded-full">{sessions.find(s=>s.id===currentSessionId)?.mode} MODE</span>}
           </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-0 animate-[fadeIn_0.5s_ease-out_forwards]">
               <div className="w-20 h-20 mb-6 relative">
                  <div className="absolute inset-0 border-t-2 border-cyan-500 rounded-full animate-spin"></div>
                  <div className="absolute inset-2 border-b-2 border-purple-500 rounded-full animate-[spin_3s_linear_infinite]"></div>
                  <div className="absolute inset-0 flex items-center justify-center font-tech text-2xl text-white">AI</div>
               </div>
               <div className="text-slate-500 font-code text-sm uppercase">{t.emptyState}</div>
            </div>
          ) : (
            <div className="max-w-4xl mx-auto space-y-8">
               {messages.map((msg) => (
                 <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-8 h-8 flex-shrink-0 flex items-center justify-center rounded-sm border ${msg.role === 'user' ? 'bg-cyan-900/20 border-cyan-500/50 text-cyan-400' : 'bg-purple-900/20 border-purple-500/50 text-purple-400'}`}>
                       {msg.role === 'user' ? t.user : t.ai}
                    </div>

                    <div className={`flex flex-col max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>

                       {/* Attachments Display */}
                       {msg.attachments && msg.attachments.length > 0 && (
                           <div className="flex flex-wrap gap-2 mb-2 justify-end">
                               {msg.attachments.map(att => (
                                   <div key={att.id} className="relative group border border-slate-700 bg-slate-900 rounded overflow-hidden w-24 h-24 flex items-center justify-center">
                                       {att.type === 'image' ? (
                                           <img src={att.url} className="w-full h-full object-cover" />
                                       ) : (
                                           <div className="text-[9px] text-center p-1 text-slate-400 break-all">{att.filename}</div>
                                       )}
                                   </div>
                               ))}
                           </div>
                       )}

                       <div className={`p-4 text-sm font-sans leading-relaxed shadow-lg whitespace-pre-wrap ${msg.role === 'user' ? 'bg-cyan-950/30 border border-cyan-500/20 text-cyan-100 rounded-bl-xl' : 'bg-slate-900/80 border border-slate-700 text-slate-300 rounded-br-xl'}`}>
                          {msg.isThinking ? <span className="animate-pulse text-purple-400">{t.processing}</span> : renderMessageContent(msg.text)}
                       </div>

                       {msg.role === 'model' && !msg.isThinking && (
                           <button onClick={() => playTTS(msg.text)} className="mt-1 text-[10px] text-slate-600 hover:text-cyan-400 flex items-center gap-1 cursor-pointer transition-colors">
                               <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                               {t.tts}
                           </button>
                       )}
                    </div>
                 </div>
               ))}
               <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 bg-slate-900/90 backdrop-blur-xl border-t border-cyan-900/30 relative z-30">
           {/* Attachment Preview Bar */}
           {attachments.length > 0 && (
               <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
                   <span className="text-xs text-cyan-500 font-code self-center mr-2">{t.attach}</span>
                   {attachments.map((att, i) => (
                       <div key={i} className="relative bg-slate-800 border border-slate-600 rounded p-1 w-12 h-12 flex items-center justify-center shrink-0">
                           {att.type==='image' ? <img src={att.url} className="w-full h-full object-cover opacity-70" /> : <span className="text-[8px] text-slate-400">FILE</span>}
                           <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-[10px] flex items-center justify-center">×</button>
                       </div>
                   ))}
               </div>
           )}

           <div className="max-w-4xl mx-auto flex gap-3 items-end">
              {/* Tools: Upload & Voice */}
              <div className="flex gap-2 pb-2">
                  <button onClick={() => fileInputRef.current?.click()} className="text-slate-500 hover:text-cyan-400 p-2 border border-transparent hover:border-slate-700 rounded transition-all">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

                  <button 
                    onMouseDown={startRecording} 
                    onMouseUp={stopRecording} 
                    className={`p-2 rounded border transition-all ${isRecording ? 'bg-red-900/50 text-red-500 border-red-500 animate-pulse' : 'text-slate-500 hover:text-cyan-400 border-transparent hover:border-slate-700'}`}
                  >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                  </button>
              </div>

              <div className="relative flex-1 group">
                 <div className="absolute -top-1 -left-1 w-2 h-2 border-t border-l border-cyan-500/50"></div>
                 <div className="absolute -bottom-1 -right-1 w-2 h-2 border-b border-r border-cyan-500/50"></div>

                 <textarea
                   ref={inputRef}
                   value={input}
                   onChange={(e) => setInput(e.target.value)}
                   onKeyDown={(e) => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                   placeholder={isRecording ? t.listening : t.placeholder}
                   className="w-full bg-black/60 border border-slate-700 text-white p-3 pr-10 focus:outline-none focus:border-cyan-500/50 transition-all font-sans resize-none custom-scrollbar max-h-32 min-h-[48px] rounded-none"
                   rows={1}
                 />
              </div>

              <button 
                onClick={() => handleSend()}
                disabled={isLoading || (!input.trim() && attachments.length===0)}
                className={`p-3 mb-1 bg-cyan-900/20 border border-cyan-500/30 text-cyan-400 hover:bg-cyan-600 hover:text-white transition-all ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export type Language = 'en' | 'zh';

export enum ImageFormat {
  ORIGINAL = 'original',
  JPEG = 'jpeg',
  PNG = 'png',
  WEBP = 'webp',
  AVIF = 'avif',
  BMP = 'bmp'
}

export type RawPixelFormat = 'uyvy' | 'nv21' | 'rgba' | 'bgra' | 'rgb' | 'bgr';

export type WatermarkPosition = 'top-left' | 'top-right' | 'center' | 'bottom-left' | 'bottom-right';

export type AITaskType = 'vision' | 'generate-image' | 'generate-video';

export interface ProcessOptions {
  format: ImageFormat;
  quality: number;
  width: number | null;
  height: number | null;
  maintainAspectRatio: boolean;
  resizeMode: 'cover' | 'contain' | 'fill' | 'inside' | 'outside';
  rotate: number;
  flipX: boolean;
  flipY: boolean;
  grayscale: boolean;
  blur: number;
  sharpen: boolean;
  watermarkText: string;
  watermarkPosition: WatermarkPosition;
  rawWidth?: number;
  rawHeight?: number;
  rawPixelFormat?: RawPixelFormat;
  // AI Options
  aiTask: AITaskType;
  aiPrompt: string;
}

export interface UploadResponse {
  id: string;
  filename: string;
  url: string;
  originalName: string;
  size: number;
  width?: number;
  height?: number;
  depth?: string;
  format?: string;
  mimeType?: string; // Added for AI Core
}

export interface ProcessResponse {
  url?: string;
  filename?: string;
  size?: number;
  // AI Specific
  aiText?: string;
  mimeType?: string; // video/mp4, image/png
}

