        abgrBuffer[i+2] = g;
        abgrBuffer[i+3] = r;
      }
      const bmpData = bmp.encode({
        data: abgrBuffer,
        width: info.width,
        height: info.height
      });
      fs.writeFileSync(outputPath, bmpData.data);
    } else {
