              <textarea ref={inputRef} value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }} placeholder={t.placeholder} className="w-full bg-black/60 border border-slate-700 text-white p-3 pr-10 focus:outline-none focus:border-cyan-500/50 font-sans resize-none custom-scrollbar max-h-32 min-h-[48px]" rows={1} />
              <button onClick={() => handleSend()} disabled={isLoading || (!input.trim() && attachments.length===0)} className={`p-3 mb-1 bg-cyan-900/20 border border-cyan-500/30 text-cyan-400 hover:bg-cyan-600 hover:text-white transition-all ${isLoading ? 'opacity-50' : ''}`}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg></button>
