  };

  const handleSend = async (textOverride?: string) => {
    const text = textOverride || input;
    if ((!text.trim() && attachments.length === 0) || isLoading) return;

    let sid = currentSessionId;
    if (!sid) {
        const res = await fetch('/api/ai/sessions', { 
          method: 'POST', 
          headers: { 'Content-Type': 'application/json' }, 
          body: JSON.stringify({ mode: 'general' }) 
        });
        const s = await res.json(); 
        setSessions(p => [s, ...p]); 
        sid = s.id; 
        setCurrentSessionId(s.id);
    }

    const atts = [...attachments];
    setMessages(p => [...p, { id: Date.now().toString(), role: 'user', text, timestamp: Date.now(), attachments: atts }]);
    setInput(''); setAttachments([]); setIsLoading(true);

    const aiMsgId = (Date.now() + 1).toString();
    setMessages(p => [...p, { id: aiMsgId, role: 'model', text: '', isThinking: true, timestamp: Date.now() + 1 }]);

    try {
      const response = await fetch('/api/ai/chat', { 
        method: 'POST', 
        headers: { 'Content-Type': 'application/json' }, 
        body: JSON.stringify({ sessionId: sid, message: text, attachments: atts, model, lang }) 
      });

      if (!response.body) throw new Error("No body");
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let acc = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        const chunk = decoder.decode(value);
        acc += chunk;

        let displayAcc = acc;
        if (acc.includes('{"error"')) {
           try {
               const parsed = JSON.parse(acc.substring(acc.indexOf('{"error"')));
               displayAcc = parsed.error?.message || t.error;
           } catch(e) {}
        }

        setMessages(p => p.map(m => m.id === aiMsgId ? { ...m, text: displayAcc, isThinking: false } : m));
      }
      setSessions(p => p.map(s => s.id === sid ? { ...s, lastMessageAt: Date.now(), preview: acc.substring(0, 50) } : s));
    } catch (e: any) {
      setMessages(p => p.map(m => m.id === aiMsgId ? { ...m, text: t.error, isThinking: false } : m));
    } finally { setIsLoading(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files?.[0]) {
          const file = e.target.files[0];
          const formData = new FormData(); formData.append('image', file);
          const res = await fetch('/api/upload', { method: 'POST', body: formData });
          const data = await res.json();
          setAttachments(p => [...p, { id: data.id, type: file.type.startsWith('image/') ? 'image' : 'file', url: data.url, filename: data.filename, mimeType: data.mimeType }]);
      }
  };

  const renderContent = (text: string) => {
      if (text.startsWith('[') && text.endsWith(']')) return <span className="text-amber-500 font-code italic bg-amber-500/10 px-2 py-1 border border-amber-500/20 block rounded">{text}</span>;
      return text.split(/(!\[.*?\]\(.*?\))/g).map((part, i) => {
          const match = part.match(/!\[(.*?)\]\((.*?)\)/);
          if (match) {
              const [_, alt, url] = match;
              return url.endsWith('.mp4') || alt.toLowerCase().includes('video') 
                ? <video key={i} src={url} controls className="my-2 w-full max-h-64 bg-black/50 rounded-lg border border-purple-600 shadow-lg" />
                : <img key={i} src={url} alt={alt} className="my-2 w-full max-h-64 object-contain bg-black/20 rounded-lg border border-slate-600 shadow-lg" />;
          }
          return <span key={i}>{part}</span>;
      });
  };

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  return (
    <div className="flex h-full bg-[#020617] text-slate-200 overflow-hidden font-sans relative">
      {/* Sidebar */}
      <div className="w-16 md:w-64 flex flex-col bg-slate-900/50 border-r border-cyan-900/30 backdrop-blur-md z-20">
        <div className="p-4">
          <button onClick={() => createSession()} className="w-full flex items-center justify-center md:justify-start gap-3 px-3 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-tech text-xs tracking-widest uppercase shadow-lg transition-all clip-button">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden md:inline">{t.newChat}</span>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
           <div className="hidden md:block text-[10px] text-slate-500 font-code px-2 mb-2 uppercase tracking-widest">{t.history}</div>
           {sessions.map(s => (
             <div key={s.id} onClick={() => setCurrentSessionId(s.id)} className={`group relative p-2 md:p-3 cursor-pointer border-l-2 transition-all ${currentSessionId === s.id ? 'bg-slate-800 border-cyan-500 text-cyan-100' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}>
                <div className="font-bold text-xs truncate w-full pr-6">{s.title || "Untitled Link"}</div>
                <div className="hidden md:block text-[10px] truncate opacity-50 mt-1">{s.preview || "No content"}</div>
             </div>
           ))}
        </div>
      </div>

      {/* Main Chat View */}
      <div className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
        <div className="h-14 border-b border-cyan-900/30 bg-slate-900/80 backdrop-blur-md flex items-center justify-between px-6 z-30">
          <div className="flex items-center gap-2">
            <span className="text-cyan-400 font-tech text-lg">{t.aiCoreTitle}</span>
            <span className="text-slate-600 font-thin mx-1">/</span>
            <select value={model} onChange={(e) => setModel(e.target.value as AIModelVersion)} className="bg-transparent text-xs font-code text-slate-300 focus:outline-none uppercase cursor-pointer hover:text-cyan-400">
               <optgroup label="GOOGLE CLOUD" className="bg-slate-900 text-cyan-400">
                  <option value="gemini-3-flash-preview">FLASH 3</option>
                  <option value="gemini-3-pro-preview">PRO 3</option>
               </optgroup>
               <optgroup label="OPENAI" className="bg-slate-900 text-green-400">
                  <option value="gpt-4o">GPT-4o</option>
               </optgroup>
            </select>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-80">
               {sessions.length === 0 ? (
                 <>
                   <div className="w-16 h-16 mb-4 border-2 border-dashed border-slate-700 flex items-center justify-center rounded-full text-slate-700">?</div>
                   <div className="text-slate-500 font-code text-xs uppercase mb-6 tracking-widest">{t.noSessions}</div>
                   <button onClick={() => createSession()} className="px-6 py-2 border border-cyan-500 text-cyan-400 font-tech text-[10px] tracking-[0.2em] hover:bg-cyan-500/10 transition-all uppercase">{t.startFirst}</button>
                 </>
               ) : (
                 <>
                   <div className="w-20 h-20 mb-6 border-t-2 border-cyan-500 rounded-full animate-spin"></div>
                   <div className="text-slate-500 font-code text-sm uppercase tracking-widest">{t.emptyState}</div>
                 </>
               )}
            </div>
          ) : (
            <div className="max-w-4xl mx-auto space-y-8">
               {messages.map((m) => (
                 <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-8 h-8 flex-shrink-0 flex items-center justify-center rounded-sm border ${m.role === 'user' ? 'bg-cyan-900/20 border-cyan-500/50 text-cyan-400' : 'bg-purple-900/20 border-purple-500/50 text-purple-400'}`}>{m.role === 'user' ? t.user : t.ai}</div>
                    <div className={`flex flex-col max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                       {m.attachments?.map((a, i) => (
                         <div key={i} className="mb-2 w-24 h-24 border border-slate-700 rounded overflow-hidden">
                           {a.type==='image'?<img src={a.url} className="w-full h-full object-cover"/>:<div className="flex flex-col items-center justify-center h-full text-[8px] text-slate-500 uppercase">FILE</div>}
                         </div>
                       ))}
                       <div className={`p-4 text-sm leading-relaxed shadow-lg whitespace-pre-wrap ${m.role === 'user' ? 'bg-cyan-950/30 border border-cyan-500/20 text-cyan-100 rounded-bl-xl' : 'bg-slate-900/80 border border-slate-700 text-slate-300 rounded-br-xl'}`}>
                         {m.isThinking ? <span className="animate-pulse text-purple-400">{t.processing}</span> : renderContent(m.text)}
                       </div>
                    </div>
                 </div>
               ))}
               <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Footer Input */}
        <div className="p-4 bg-slate-900/90 backdrop-blur-xl border-t border-cyan-900/30">
           {attachments.length > 0 && (
             <div className="flex gap-2 mb-2 overflow-x-auto pb-1">
               {attachments.map((a, i) => (
                 <div key={i} className="relative bg-slate-800 border border-slate-600 rounded p-1 w-12 h-12 flex items-center justify-center shrink-0">
                    {a.type==='image' ? <img src={a.url} className="w-full h-full object-cover opacity-70" /> : <div className="text-[8px] text-slate-400 uppercase">FILE</div>}
                    <button onClick={() => setAttachments(p => p.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-[10px] flex items-center justify-center">×</button>
                 </div>
               ))}
             </div>
           )}
           <div className="max-w-4xl mx-auto flex gap-3 items-end">
              <div className="flex gap-2 pb-2">
                <button onClick={() => fileInputRef.current?.click()} className="text-slate-500 hover:text-cyan-400 p-2 border border-transparent hover:border-slate-700 rounded transition-all">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
              </div>
              <div className="flex-1 relative">
                <textarea ref={inputRef} value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }} placeholder={t.placeholder} className="w-full bg-black/60 border border-slate-700 text-white p-3 pr-10 focus:outline-none focus:border-cyan-500/50 font-sans resize-none custom-scrollbar max-h-32 min-h-[48px] rounded-none" rows={1} />
              </div>
              <button onClick={() => handleSend()} disabled={isLoading || (!input.trim() && attachments.length===0)} className={`p-3 mb-1 bg-cyan-900/20 border border-cyan-500/30 text-cyan-400 hover:bg-cyan-600 hover:text-white transition-all ${isLoading ? 'opacity-50' : ''}`}>
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Language, ChatMessage, AIModelVersion, ChatSession, AIWorkMode, AIAttachment } from '../types';

interface AICoreProps {
  lang: Language;
}

export const AICore: React.FC<AICoreProps> = ({ lang }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [model, setModel] = useState<AIModelVersion>('gemini-3-flash-preview');
  const [attachments, setAttachments] = useState<AIAttachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Guard to prevent history loading from interrupting a fresh chat
  const isSendingRef = useRef(false);

  const t = {
    en: { 
      aiCoreTitle: "AI_CORE", 
      newChat: "NEW SESSION", 
      placeholder: "Broadcast message to core...", 
      modelFlash: "GEMINI 3 FLASH", 
      modelPro: "GEMINI 3 PRO", 
      history: "SESSIONS", 
      emptyState: "AWAITING INPUT STREAM...", 
      noSessions: "NO ACTIVE NEURAL LINKS",
      startFirst: "INITIATE FIRST LINK",
      processing: "PROCESSING...", 
      error: "Error: Neural Link Failed.", 
      user: "U", 
      ai: "AI", 
      cost: "COST", 
      iq: "IQ"
    },
    zh: { 
      aiCoreTitle: "AI 核心", 
      newChat: "新建会话", 
      placeholder: "输入指令或提问...", 
      modelFlash: "GEMINI 3 FLASH", 
      modelPro: "GEMINI 3 PRO", 
      history: "历史会话", 
      emptyState: "等待输入信号...", 
      noSessions: "当前无活跃神经连接",
      startFirst: "开启首个会话",
      processing: "计算中...", 
      error: "错误：神经连接中断。", 
      user: "我", 
      ai: "AI", 
      cost: "成本", 
      iq: "智商"
    }
  }[lang];

  useEffect(() => { 
    fetch('/api/ai/sessions')
      .then(r => r.json())
      .then(data => {
        setSessions(data);
        if (data.length > 0 && !currentSessionId) {
          setCurrentSessionId(data[0].id);
        }
      });
  }, []);

  useEffect(() => { 
    // Only load history if we aren't currently sending a message (which manually manages state)
    if (currentSessionId && !isSendingRef.current) {
      loadSessionHistory(currentSessionId); 
    }
  }, [currentSessionId]);

  const loadSessionHistory = async (id: string) => {
    setMessages([]); 
    try {
        const res = await fetch(`/api/ai/sessions/${id}`);
        if (!res.ok) return;
        const data = await res.json();
        if (data.history) {
            setMessages(data.history.map((h: any, i: number) => ({
                id: `msg-${i}-${Date.now()}`, 
                role: h.role === 'model' ? 'model' : 'user', 
                text: (h.parts || []).map((p:any) => p.text || "").join(""),
                attachments: (h.parts || []).filter((p:any) => p.inlineData).map((p:any) => ({ 
                  id: `att-${i}-${Math.random()}`, 
                  type: 'image', 
                  url: `data:${p.inlineData.mimeType};base64,${p.inlineData.data}` 
                }))
            })));
        }
    } catch (e) {}
  };

  const createSession = async (mode: AIWorkMode = 'general') => {
    try {
      const res = await fetch('/api/ai/sessions', { 
        method: 'POST', 
        headers: { 'Content-Type': 'application/json' }, 
        body: JSON.stringify({ mode }) 
      });
      const s = await res.json(); 
      setSessions(p => [s, ...p]); 
      setCurrentSessionId(s.id);
      setMessages([]);
    } catch (e) { console.error(e); }
  };

  const handleSend = async (textOverride?: string) => {
    const text = textOverride || input;
    if ((!text.trim() && attachments.length === 0) || isLoading) return;

    isSendingRef.current = true;
    setIsLoading(true);

    let sid = currentSessionId;
    if (!sid) {
        try {
          const res = await fetch('/api/ai/sessions', { 
            method: 'POST', 
            headers: { 'Content-Type': 'application/json' }, 
            body: JSON.stringify({ mode: 'general' }) 
          });
          const s = await res.json(); 
          setSessions(p => [s, ...p]); 
          sid = s.id; 
          setCurrentSessionId(s.id);
        } catch (e) {
          setIsLoading(false);
          isSendingRef.current = false;
          alert("Failed to initialize link");
          return;
        }
    }

    const atts = [...attachments];
    setMessages(p => [...p, { id: Date.now().toString(), role: 'user', text, timestamp: Date.now(), attachments: atts }]);
    setInput(''); setAttachments([]);

    const aiMsgId = (Date.now() + 1).toString();
    setMessages(p => [...p, { id: aiMsgId, role: 'model', text: '', isThinking: true, timestamp: Date.now() + 1 }]);

    try {
      const response = await fetch('/api/ai/chat', { 
        method: 'POST', 
        headers: { 'Content-Type': 'application/json' }, 
        body: JSON.stringify({ sessionId: sid, message: text, attachments: atts, model, lang }) 
      });

      if (!response.body) throw new Error("No body");
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let acc = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        const chunk = decoder.decode(value);
        acc += chunk;

        let displayAcc = acc;
        if (acc.includes('{"error"')) {
           try {
               const parsed = JSON.parse(acc.substring(acc.indexOf('{"error"')));
               displayAcc = parsed.error?.message || t.error;
           } catch(e) {}
        }

        setMessages(p => p.map(m => m.id === aiMsgId ? { ...m, text: displayAcc, isThinking: false } : m));
      }
      setSessions(p => p.map(s => s.id === sid ? { ...s, lastMessageAt: Date.now(), preview: acc.substring(0, 50) } : s));
    } catch (e: any) {
      setMessages(p => p.map(m => m.id === aiMsgId ? { ...m, text: t.error, isThinking: false } : m));
    } finally { 
      setIsLoading(false); 
      isSendingRef.current = false;
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files?.[0]) {
          const file = e.target.files[0];
          const formData = new FormData(); formData.append('image', file);
          const res = await fetch('/api/upload', { method: 'POST', body: formData });
          const data = await res.json();
          setAttachments(p => [...p, { id: data.id, type: file.type.startsWith('image/') ? 'image' : 'file', url: data.url, filename: data.filename, mimeType: data.mimeType }]);
      }
  };

  const renderContent = (text: string) => {
      if (text.startsWith('[') && text.endsWith(']')) return <span className="text-amber-500 font-code italic bg-amber-500/10 px-2 py-1 border border-amber-500/20 block rounded">{text}</span>;
      return text.split(/(!\[.*?\]\(.*?\))/g).map((part, i) => {
          const match = part.match(/!\[(.*?)\]\((.*?)\)/);
          if (match) {
              const [_, alt, url] = match;
              return url.endsWith('.mp4') || alt.toLowerCase().includes('video') 
                ? <video key={i} src={url} controls className="my-2 w-full max-h-64 bg-black/50 rounded-lg border border-purple-600 shadow-lg" />
                : <img key={i} src={url} alt={alt} className="my-2 w-full max-h-64 object-contain bg-black/20 rounded-lg border border-slate-600 shadow-lg" />;
          }
          return <span key={i}>{part}</span>;
      });
  };

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  return (
    <div className="flex h-full bg-[#020617] text-slate-200 overflow-hidden font-sans relative">
      <div className="w-16 md:w-64 flex flex-col bg-slate-900/50 border-r border-cyan-900/30 backdrop-blur-md z-20">
        <div className="p-4">
          <button onClick={() => createSession()} className="w-full flex items-center justify-center md:justify-start gap-3 px-3 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-tech text-xs tracking-widest uppercase shadow-lg transition-all clip-button">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden md:inline">{t.newChat}</span>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
           <div className="hidden md:block text-[10px] text-slate-500 font-code px-2 mb-2 uppercase tracking-widest">{t.history}</div>
           {sessions.map(s => (
             <div key={s.id} onClick={() => setCurrentSessionId(s.id)} className={`group relative p-2 md:p-3 cursor-pointer border-l-2 transition-all ${currentSessionId === s.id ? 'bg-slate-800 border-cyan-500 text-cyan-100' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}>
                <div className="font-bold text-xs truncate w-full pr-6">{s.title || "Untitled Link"}</div>
                <div className="hidden md:block text-[10px] truncate opacity-50 mt-1">{s.preview || "No content"}</div>
             </div>
           ))}
        </div>
      </div>

      <div className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
        <div className="h-14 border-b border-cyan-900/30 bg-slate-900/80 backdrop-blur-md flex items-center justify-between px-6 z-30">
          <div className="flex items-center gap-2">
            <span className="text-cyan-400 font-tech text-lg">{t.aiCoreTitle}</span>
            <span className="text-slate-600 font-thin mx-1">/</span>
            <select value={model} onChange={(e) => setModel(e.target.value as AIModelVersion)} className="bg-transparent text-xs font-code text-slate-300 focus:outline-none uppercase cursor-pointer hover:text-cyan-400">
               <optgroup label="GOOGLE CLOUD" className="bg-slate-900 text-cyan-400">
                  <option value="gemini-3-flash-preview">FLASH 3</option>
                  <option value="gemini-3-pro-preview">PRO 3</option>
               </optgroup>
               <optgroup label="OPENAI" className="bg-slate-900 text-green-400">
                  <option value="gpt-4o">GPT-4o</option>
               </optgroup>
            </select>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-80">
               {sessions.length === 0 ? (
                 <>
                   <div className="w-16 h-16 mb-4 border-2 border-dashed border-slate-700 flex items-center justify-center rounded-full text-slate-700">?</div>
                   <div className="text-slate-500 font-code text-xs uppercase mb-6 tracking-widest">{t.noSessions}</div>
                   <button onClick={() => createSession()} className="px-6 py-2 border border-cyan-500 text-cyan-400 font-tech text-[10px] tracking-[0.2em] hover:bg-cyan-500/10 transition-all uppercase">{t.startFirst}</button>
                 </>
               ) : (
                 <>
                   <div className="w-20 h-20 mb-6 border-t-2 border-cyan-500 rounded-full animate-spin"></div>
                   <div className="text-slate-500 font-code text-sm uppercase tracking-widest">{t.emptyState}</div>
                 </>
               )}
            </div>
          ) : (
            <div className="max-w-4xl mx-auto space-y-8">
               {messages.map((m) => (
                 <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-8 h-8 flex-shrink-0 flex items-center justify-center rounded-sm border ${m.role === 'user' ? 'bg-cyan-900/20 border-cyan-500/50 text-cyan-400' : 'bg-purple-900/20 border-purple-500/50 text-purple-400'}`}>{m.role === 'user' ? t.user : t.ai}</div>
                    <div className={`flex flex-col max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                       {m.attachments?.map((a, i) => (
                         <div key={i} className="mb-2 w-24 h-24 border border-slate-700 rounded overflow-hidden">
                           {a.type==='image'?<img src={a.url} className="w-full h-full object-cover"/>:<div className="flex flex-col items-center justify-center h-full text-[8px] text-slate-500 uppercase">FILE</div>}
                         </div>
                       ))}
                       <div className={`p-4 text-sm leading-relaxed shadow-lg whitespace-pre-wrap ${m.role === 'user' ? 'bg-cyan-950/30 border border-cyan-500/20 text-cyan-100 rounded-bl-xl' : 'bg-slate-900/80 border border-slate-700 text-slate-300 rounded-br-xl'}`}>
                         {m.isThinking ? <span className="animate-pulse text-purple-400">{t.processing}</span> : renderContent(m.text)}
                       </div>
                    </div>
                 </div>
               ))}
               <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        <div className="p-4 bg-slate-900/90 backdrop-blur-xl border-t border-cyan-900/30">
           {attachments.length > 0 && (
             <div className="flex gap-2 mb-2 overflow-x-auto pb-1">
               {attachments.map((a, i) => (
                 <div key={i} className="relative bg-slate-800 border border-slate-600 rounded p-1 w-12 h-12 flex items-center justify-center shrink-0">
                    {a.type==='image' ? <img src={a.url} className="w-full h-full object-cover opacity-70" /> : <div className="text-[8px] text-slate-400 uppercase">FILE</div>}
                    <button onClick={() => setAttachments(p => p.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-[10px] flex items-center justify-center">×</button>
                 </div>
               ))}
             </div>
           )}
           <div className="max-w-4xl mx-auto flex gap-3 items-end">
              <div className="flex gap-2 pb-2">
                <button onClick={() => fileInputRef.current?.click()} className="text-slate-500 hover:text-cyan-400 p-2 border border-transparent hover:border-slate-700 rounded transition-all">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
              </div>
              <div className="flex-1 relative">
                <textarea ref={inputRef} value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }} placeholder={t.placeholder} className="w-full bg-black/60 border border-slate-700 text-white p-3 pr-10 focus:outline-none focus:border-cyan-500/50 font-sans resize-none custom-scrollbar max-h-32 min-h-[48px] rounded-none" rows={1} />
              </div>
              <button onClick={() => handleSend()} disabled={isLoading || (!input.trim() && attachments.length===0)} className={`p-3 mb-1 bg-cyan-900/20 border border-cyan-500/30 text-cyan-400 hover:bg-cyan-600 hover:text-white transition-all ${isLoading ? 'opacity-50' : ''}`}>
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Language, ChatMessage, AIModelVersion, ChatSession, AIWorkMode, AIAttachment } from '../types';

interface AICoreProps {
  lang: Language;
}

export const AICore: React.FC<AICoreProps> = ({ lang }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [model, setModel] = useState<AIModelVersion>('gemini-3-flash-preview');

  // Attachments & Audio
  const [attachments, setAttachments] = useState<AIAttachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // CRITICAL: Guard to prevent history loading from clearing active messages during a live chat stream
  const isSendingRef = useRef(false);

  const t = {
    en: {
      aiCoreTitle: "AI_CORE",
      newChat: "NEW SESSION",
      placeholder: "Broadcast message to core...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      modelFlashLatest: "GEMINI FLASH",
      modelLite: "GEMINI LITE",
      history: "SESSIONS",
      modes: "WORK MODE",
      modeGen: "GENERAL",
      modeCode: "ENGINEER",
      modeData: "ANALYST",
      modeCreate: "CREATIVE",
      upload: "UPLOAD FILE",
      voice: "VOICE",
      listening: "LISTENING...",
      attach: "ATTACHED RES:",
      play: "PLAY",
      tts: "READ ALOUD",
      emptyState: "AWAITING INPUT STREAM...",
      processing: "PROCESSING...",
      error: "Error: Neural Link Failed.",
      user: "U",
      ai: "AI",
      cost: "COST",
      iq: "IQ",
      speed: "SPD"
    },
    zh: {
      aiCoreTitle: "AI 核心",
      newChat: "新建会话",
      placeholder: "输入指令或提问...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      modelFlashLatest: "GEMINI FLASH",
      modelLite: "GEMINI LITE",
      history: "历史会话",
      modes: "工作模式",
      modeGen: "通用助手",
      modeCode: "赛博工程师",
      modeData: "数据分析师",
      modeCreate: "创意总监",
      upload: "上传文件",
      voice: "语音输入",
      listening: "正在聆听...",
      attach: "已挂载资源:",
      play: "播放",
      tts: "朗读",
      emptyState: "等待输入信号...",
      processing: "计算中...",
      error: "错误：神经连接中断。",
      user: "我",
      ai: "AI",
      cost: "成本",
      iq: "智商",
      speed: "速度"
    }
  }[lang];

  const modeLabels: Record<string, string> = {
      general: t.modeGen,
      coder: t.modeCode,
      analyst: t.modeData,
      creative: t.modeCreate
  };

  const modelMeta: Record<string, { cost: number; iq: number; speed: number; label?: string }> = {
      'gemini-flash-lite-latest': { cost: 1, iq: 3, speed: 5, label: "VALUE" },
      'gemini-flash-latest':      { cost: 2, iq: 4, speed: 5, label: "FAST" },
      'gemini-3-flash-preview':   { cost: 3, iq: 4, speed: 4, label: "BALANCED" },
      'gemini-3-pro-preview':     { cost: 5, iq: 5, speed: 3, label: "MAX INTEL" },
      'gpt-4o':                   { cost: 5, iq: 5, speed: 4, label: "OPENAI" },
      'gpt-4-turbo':              { cost: 4, iq: 5, speed: 4, label: "LEGACY" },
      'llama-3-local':            { cost: 0, iq: 3, speed: 5, label: "LOCAL" },
      'stable-diffusion-xl':      { cost: 0, iq: 0, speed: 2, label: "IMAGE ONLY" }
  };

  useEffect(() => {
    fetchSessions();
  }, []);

  useEffect(() => {
      // FIX: Only load history if we are NOT currently sending a new message
      if (currentSessionId && !isSendingRef.current) {
          loadSessionHistory(currentSessionId);
      }
  }, [currentSessionId]);

  const fetchSessions = async () => {
    try {
      const res = await fetch('/api/ai/sessions');
      const data = await res.json();
      setSessions(data);
      if (data.length > 0 && !currentSessionId) {
          setCurrentSessionId(data[0].id);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const loadSessionHistory = async (id: string) => {
    setMessages([]); 
    try {
        const res = await fetch(`/api/ai/sessions/${id}`);
        if (!res.ok) return;
        const sessionData = await res.json();

        if (sessionData.history && Array.isArray(sessionData.history)) {
            const convertedMessages: ChatMessage[] = sessionData.history.map((h: any, index: number) => {
                let text = "";
                const atts: AIAttachment[] = [];

                if (h.parts) {
                    h.parts.forEach((p: any) => {
                        if (p.text) text += p.text;
                        if (p.inlineData) {
                            atts.push({
                                id: `hist-att-${index}-${Date.now()}-${Math.random()}`,
                                type: 'image',
                                url: `data:${p.inlineData.mimeType};base64,${p.inlineData.data}`,
                                filename: 'history_asset',
                                mimeType: p.inlineData.mimeType,
                                data: p.inlineData.data
                            });
                        }
                    });
                }

                return {
                    id: `msg-hist-${index}-${Date.now()}-${Math.random()}`,
                    role: h.role === 'model' ? 'model' : 'user',
                    text: text,
                    timestamp: Date.now(),
                    attachments: atts.length > 0 ? atts : undefined
                };
            });
            setMessages(convertedMessages);
        }
    } catch (e) {
        console.error("Failed to load history", e);
    }
  };

  const createSession = async (mode: AIWorkMode = 'general') => {
    const res = await fetch('/api/ai/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode })
    });
    const newSession = await res.json();
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    setMessages([]);
  };

  const deleteSession = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      await fetch(`/api/ai/sessions/${id}`, { method: 'DELETE' });
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
          setCurrentSessionId(null);
          setMessages([]);
      }
  };

  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if ((!textToSend.trim() && attachments.length === 0) || isLoading) return;

    // FIX: Set sending flag to prevent history reload
    isSendingRef.current = true;
    setIsLoading(true);

    let activeSessionId = currentSessionId;
    if (!activeSessionId) {
        try {
            const res = await fetch('/api/ai/sessions', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'general' }) });
            const newS = await res.json();
            setSessions(prev => [newS, ...prev]);
            activeSessionId = newS.id;
            setCurrentSessionId(newS.id);
        } catch (e) {
            console.error("Failed to create session", e);
            setIsLoading(false);
            isSendingRef.current = false;
            return;
        }
    }

    const tempAttachments = [...attachments];
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      timestamp: Date.now(),
      attachments: tempAttachments
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachments([]);

    const aiMsgId = (Date.now() + 1).toString();
    const aiMsgPlaceholder: ChatMessage = {
      id: aiMsgId,
      role: 'model',
      text: '',
      timestamp: Date.now() + 1,
      isThinking: true
    };
    setMessages(prev => [...prev, aiMsgPlaceholder]);

    try {
      const response = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId: activeSessionId,
          message: textToSend,
          attachments: tempAttachments,
          model: model,
          lang: lang
        })
      });

      if (!response.body) throw new Error("No response");

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let done = false;
      let accumulatedText = '';

      while (!done) {
        const { value, done: doneReading } = await reader.read();
        done = doneReading;
        const chunkValue = decoder.decode(value, { stream: !done });
        accumulatedText += chunkValue;

        setMessages(prev => prev.map(msg => 
          msg.id === aiMsgId 
            ? { ...msg, text: accumulatedText, isThinking: false } 
            : msg
        ));
      }

      setSessions(prev => prev.map(s => s.id === activeSessionId ? { ...s, lastMessageAt: Date.now(), preview: accumulatedText.substring(0, 50) } : s));

    } catch (error) {
      console.error(error);
      setMessages(prev => prev.map(msg => 
        msg.id === aiMsgId ? { ...msg, text: t.error, isThinking: false } : msg
      ));
    } finally {
      setIsLoading(false);
      // FIX: Release sending flag
      isSendingRef.current = false;
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];
          const formData = new FormData();
          formData.append('image', file);

          try {
              const res = await fetch('/api/upload', { method: 'POST', body: formData });
              const data = await res.json();

              const newAtt: AIAttachment = {
                  id: data.id,
                  type: file.type.startsWith('image/') ? 'image' : 'file',
                  url: data.url,
                  filename: data.filename,
                  mimeType: data.mimeType || file.type
              };
              setAttachments(prev => [...prev, newAtt]);
          } catch (e) { console.error(e); alert("Upload Failed"); }
      }
  };

  const startRecording = async () => {
      try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          const mediaRecorder = new MediaRecorder(stream);
          mediaRecorderRef.current = mediaRecorder;
          const chunks: Blob[] = [];

          mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
          mediaRecorder.onstop = async () => {
              const blob = new Blob(chunks, { type: 'audio/webm' });
              const formData = new FormData();
              formData.append('audio', blob, 'voice_input.webm');

              setIsLoading(true);
              try {
                  const res = await fetch('/api/ai/transcribe', { method: 'POST', body: formData });
                  const data = await res.json();
                  if (data.text) {
                      handleSend(data.text);
                  }
              } catch (e) { console.error(e); } finally { setIsLoading(false); }
          };

          mediaRecorder.start();
          setIsRecording(true);
      } catch (e) { alert("Mic Access Denied"); }
  };

  const stopRecording = () => {
      mediaRecorderRef.current?.stop();
      setIsRecording(false);
  };

  const playTTS = async (text: string) => {
      try {
          const cleanText = text.replace(/!\[.*?\]\(.*?\)/g, '');
          const res = await fetch('/api/ai/tts', { 
              method: 'POST', 
              headers: { 'Content-Type': 'application/json' }, 
              body: JSON.stringify({ text: cleanText }) 
          });
          const data = await res.json();
          if (data.audio) {
              const audio = new Audio(`data:audio/wav;base64,${data.audio}`);
              audio.play();
          }
      } catch (e) { console.error(e); }
  };

  const renderMessageContent = (text: string) => {
      const parts = text.split(/(!\[.*?\]\(.*?\))/g);
      return parts.map((part, index) => {
          const imgMatch = part.match(/!\[(.*?)\]\((.*?)\)/);
          if (imgMatch) {
              const alt = imgMatch[1];
              const url = imgMatch[2];

              if (url.endsWith('.mp4') || alt.toLowerCase().includes('video')) {
                   return (
                      <div key={index} className="my-2 rounded-lg overflow-hidden border border-purple-600 shadow-lg relative group">
                          <video src={url} controls className="w-full max-h-64 bg-black/50" />
                          <div className="bg-purple-900/50 p-1 text-[10px] text-purple-300 font-code text-center">GENERATED_VEO_ASSET</div>
                      </div>
                   );
              }

              return (
                  <div key={index} className="my-2 rounded-lg overflow-hidden border border-slate-600 shadow-lg">
                      <img src={url} alt={alt} className="w-full max-h-64 object-contain bg-black/20" />
                      <div className="bg-slate-900/50 p-1 text-[10px] text-slate-500 font-code text-center">GENERATED_ASSET</div>
                  </div>
              );
          }
          return <span key={index}>{part}</span>;
      });
  };

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  const currentMeta = modelMeta[model] || { cost: 0, iq: 0, speed: 0 };

  return (
    <div className="flex h-full bg-[#020617] text-slate-200 overflow-hidden font-sans relative">
      <div className="w-16 md:w-64 flex flex-col bg-slate-900/50 border-r border-cyan-900/30 backdrop-blur-md z-20 transition-all">
        <div className="p-4 flex flex-col gap-2">
          <button onClick={() => createSession('general')} className="w-full flex items-center justify-center md:justify-start gap-3 px-3 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-tech text-xs tracking-widest uppercase shadow-lg transition-all clip-button">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden md:inline">{t.newChat}</span>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
           <div className="hidden md:block text-[10px] text-slate-500 font-code uppercase tracking-widest mb-2 px-2">{t.history}</div>
           <div className="space-y-1">
             {sessions.map(s => (
               <div key={s.id} onClick={() => setCurrentSessionId(s.id)} className={`group relative p-2 md:p-3 cursor-pointer border-l-2 transition-all ${currentSessionId === s.id ? 'bg-slate-800 border-cyan-500 text-cyan-100' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}>
                  <div className="flex justify-between items-center">
                      <div className="font-bold text-xs truncate w-full pr-6">{s.title || "Untitled Link"}</div>
                      <button onClick={(e) => deleteSession(s.id, e)} className="absolute right-2 opacity-0 group-hover:opacity-100 text-slate-600 hover:text-rose-500">×</button>
                  </div>
                  <div className="hidden md:block text-[10px] font-code truncate opacity-70 mt-1">{s.preview}</div>
               </div>
             ))}
           </div>
        </div>
        <div className="p-2 border-t border-slate-800 hidden md:block">
            <div className="text-[10px] text-slate-500 font-code mb-2">{t.modes}</div>
            <div className="grid grid-cols-2 gap-1">
                {(['general', 'coder', 'analyst', 'creative'] as AIWorkMode[]).map(m => (
                    <button key={m} onClick={() => createSession(m)} className="text-[9px] border border-slate-700 p-1 hover:border-cyan-500 hover:text-cyan-400 uppercase transition-colors">
                        {modeLabels[m]} 
                    </button>
                ))}
            </div>
        </div>
      </div>
      <div className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
        <div className="h-16 md:h-14 border-b border-cyan-900/30 bg-slate-900/80 backdrop-blur-md flex flex-col md:flex-row items-start md:items-center justify-between px-4 md:px-6 z-30 py-2 md:py-0 gap-2 md:gap-0">
           <div className="flex flex-col md:flex-row items-start md:items-center gap-2 md:gap-4 w-full md:w-auto">
              <div className="flex items-center gap-2">
                <span className="text-cyan-400 font-tech text-lg">{t.aiCoreTitle}</span>
                <span className="text-slate-600 font-thin">/</span>
                <select value={model} onChange={(e) => setModel(e.target.value as AIModelVersion)} className="bg-transparent text-xs font-code text-slate-300 focus:outline-none uppercase cursor-pointer hover:text-cyan-400 max-w-[200px] md:max-w-none">
                   <optgroup label="GOOGLE CLOUD" className="bg-slate-900 text-cyan-400">
                     <option value="gemini-3-flash-preview">{t.modelFlash}</option>
                     <option value="gemini-3-pro-preview">{t.modelPro}</option>
                     <option value="gemini-flash-latest">{t.modelFlashLatest}</option>
                     <option value="gemini-flash-lite-latest">{t.modelLite}</option>
                   </optgroup>
                   <optgroup label="OPENAI" className="bg-slate-900 text-green-400">
                     <option value="gpt-4o">GPT-4o</option>
                     <option value="gpt-4-turbo">GPT-4 TURBO</option>
                   </optgroup>
                </select>
              </div>
              <div className="flex items-center gap-3 bg-black/20 px-2 py-1 rounded border border-white/5">
                 <div className="flex items-center gap-1">
                    <span className="text-[9px] text-slate-500 font-code uppercase">{t.cost}</span>
                    <div className="flex gap-0.5">
                       {[...Array(5)].map((_, i) => (
                          <div key={i} className={`w-1 h-2 rounded-sm ${i < currentMeta.cost ? 'bg-emerald-500' : 'bg-slate-800'}`}></div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-80">
               <div className="w-20 h-20 mb-6 relative">
                  <div className="absolute inset-0 border-t-2 border-cyan-500 rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center font-tech text-2xl text-white">AI</div>
               </div>
               <div className="text-slate-500 font-code text-sm uppercase">{t.emptyState}</div>
            </div>
          ) : (
            <div className="max-w-4xl mx-auto space-y-8">
               {messages.map((msg) => (
                 <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-8 h-8 flex-shrink-0 flex items-center justify-center rounded-sm border ${msg.role === 'user' ? 'bg-cyan-900/20 border-cyan-500/50 text-cyan-400' : 'bg-purple-900/20 border-purple-500/50 text-purple-400'}`}>
                       {msg.role === 'user' ? t.user : t.ai}
                    </div>
                    <div className={`flex flex-col max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                       {msg.attachments && msg.attachments.length > 0 && (
                           <div className="flex flex-wrap gap-2 mb-2 justify-end">
                               {msg.attachments.map(att => (
                                   <div key={att.id} className="relative group border border-slate-700 bg-slate-900 rounded overflow-hidden w-24 h-24 flex items-center justify-center">
                                       {att.type === 'image' ? <img src={att.url} className="w-full h-full object-cover" /> : <div className="text-[8px] text-slate-500">FILE</div>}
                                   </div>
                               ))}
                           </div>
                       )}
                       <div className={`p-4 text-sm font-sans leading-relaxed shadow-lg whitespace-pre-wrap ${msg.role === 'user' ? 'bg-cyan-950/30 border border-cyan-500/20 text-cyan-100 rounded-bl-xl' : 'bg-slate-900/80 border border-slate-700 text-slate-300 rounded-br-xl'}`}>
                          {msg.isThinking ? <span className="animate-pulse text-purple-400">{t.processing}</span> : renderMessageContent(msg.text)}
                       </div>
                    </div>
                 </div>
               ))}
               <div ref={messagesEndRef} />
            </div>
          )}
        </div>
        <div className="p-4 bg-slate-900/90 backdrop-blur-xl border-t border-cyan-900/30 relative z-30">
           {attachments.length > 0 && (
               <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
                   {attachments.map((att, i) => (
                       <div key={i} className="relative bg-slate-800 border border-slate-600 rounded p-1 w-12 h-12 flex items-center justify-center shrink-0">
                           {att.type==='image' ? <img src={att.url} className="w-full h-full object-cover opacity-70" /> : <span className="text-[8px] text-slate-400">FILE</span>}
                           <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-[10px] flex items-center justify-center">×</button>
                       </div>
                   ))}
               </div>
           )}
           <div className="max-w-4xl mx-auto flex gap-3 items-end">
              <div className="flex gap-2 pb-2">
                  <button onClick={() => fileInputRef.current?.click()} className="text-slate-500 hover:text-cyan-400 p-2 border border-transparent hover:border-slate-700 rounded transition-all">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
              </div>
              <textarea
                ref={inputRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                placeholder={t.placeholder}
                className="w-full bg-black/60 border border-slate-700 text-white p-3 pr-10 focus:outline-none focus:border-cyan-500/50 transition-all font-sans resize-none custom-scrollbar max-h-32 min-h-[48px] rounded-none"
                rows={1}
              />
              <button 
                onClick={() => handleSend()}
                disabled={isLoading || (!input.trim() && attachments.length===0)}
                className={`p-3 mb-1 bg-cyan-900/20 border border-cyan-500/30 text-cyan-400 hover:bg-cyan-600 hover:text-white transition-all ${isLoading ? 'opacity-50' : ''}`}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Language, ChatMessage, AIModelVersion, ChatSession, AIWorkMode, AIAttachment } from '../types';

interface AICoreProps {
  lang: Language;
}

export const AICore: React.FC<AICoreProps> = ({ lang }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [model, setModel] = useState<AIModelVersion>('gemini-3-flash-preview');

  // Attachments & Audio
  const [attachments, setAttachments] = useState<AIAttachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // FIX: Guard to prevent history loading from clearing active messages during a live chat stream
  const isSendingRef = useRef(false);

  const t = {
    en: {
      aiCoreTitle: "AI_CORE",
      newChat: "NEW SESSION",
      placeholder: "Broadcast message to core...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      modelFlashLatest: "GEMINI FLASH",
      modelLite: "GEMINI LITE",
      history: "SESSIONS",
      modes: "WORK MODE",
      modeGen: "GENERAL",
      modeCode: "ENGINEER",
      modeData: "ANALYST",
      modeCreate: "CREATIVE",
      upload: "UPLOAD FILE",
      voice: "VOICE",
      listening: "LISTENING...",
      attach: "ATTACHED RES:",
      play: "PLAY",
      tts: "READ ALOUD",
      emptyState: "AWAITING INPUT STREAM...",
      processing: "PROCESSING...",
      error: "Error: Neural Link Failed.",
      user: "U",
      ai: "AI",
      cost: "COST",
      iq: "IQ",
      speed: "SPD"
    },
    zh: {
      aiCoreTitle: "AI 核心",
      newChat: "新建会话",
      placeholder: "输入指令或提问...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      modelFlashLatest: "GEMINI FLASH",
      modelLite: "GEMINI LITE",
      history: "历史会话",
      modes: "工作模式",
      modeGen: "通用助手",
      modeCode: "赛博工程师",
      modeData: "数据分析师",
      modeCreate: "创意总监",
      upload: "上传文件",
      voice: "语音输入",
      listening: "正在聆听...",
      attach: "已挂载资源:",
      play: "播放",
      tts: "朗读",
      emptyState: "等待输入信号...",
      processing: "计算中...",
      error: "错误：神经连接中断。",
      user: "我",
      ai: "AI",
      cost: "成本",
      iq: "智商",
      speed: "速度"
    }
  }[lang];

  const modeLabels: Record<string, string> = {
      general: t.modeGen,
      coder: t.modeCode,
      analyst: t.modeData,
      creative: t.modeCreate
  };

  // Model Metadata for UI
  const modelMeta: Record<string, { cost: number; iq: number; speed: number; label?: string }> = {
      'gemini-flash-lite-latest': { cost: 1, iq: 3, speed: 5, label: "VALUE" },
      'gemini-flash-latest':      { cost: 2, iq: 4, speed: 5, label: "FAST" },
      'gemini-3-flash-preview':   { cost: 3, iq: 4, speed: 4, label: "BALANCED" },
      'gemini-3-pro-preview':     { cost: 5, iq: 5, speed: 3, label: "MAX INTEL" },
      'gpt-4o':                   { cost: 5, iq: 5, speed: 4, label: "OPENAI" },
      'gpt-4-turbo':              { cost: 4, iq: 5, speed: 4, label: "LEGACY" },
      'llama-3-local':            { cost: 0, iq: 3, speed: 5, label: "LOCAL" },
      'stable-diffusion-xl':      { cost: 0, iq: 0, speed: 2, label: "IMAGE ONLY" }
  };

  // --- Session Management ---
  useEffect(() => {
    fetchSessions();
  }, []);

  // Sync History when session ID changes
  useEffect(() => {
      // FIX: Only load history if we are NOT currently sending a message
      if (currentSessionId && !isSendingRef.current) {
          loadSessionHistory(currentSessionId);
      }
  }, [currentSessionId]);

  const fetchSessions = async () => {
    try {
      const res = await fetch('/api/ai/sessions');
      const data = await res.json();
      setSessions(data);
    } catch (e) {
      console.error(e);
    }
  };

  const loadSessionHistory = async (id: string) => {
    setMessages([]); 
    try {
        const res = await fetch(`/api/ai/sessions/${id}`);
        if (!res.ok) return;
        const sessionData = await res.json();

        if (sessionData.history && Array.isArray(sessionData.history)) {
            const convertedMessages: ChatMessage[] = sessionData.history.map((h: any, index: number) => {
                let text = "";
                const atts: AIAttachment[] = [];

                if (h.parts) {
                    h.parts.forEach((p: any) => {
                        if (p.text) text += p.text;
                        if (p.inlineData) {
                            atts.push({
                                id: `hist-att-${index}-${Date.now()}-${Math.random()}`,
                                type: 'image',
                                url: `data:${p.inlineData.mimeType};base64,${p.inlineData.data}`,
                                filename: 'history_asset',
                                mimeType: p.inlineData.mimeType,
                                data: p.inlineData.data
                            });
                        }
                    });
                }

                return {
                    id: `msg-hist-${index}-${Date.now()}`,
                    role: h.role === 'model' ? 'model' : 'user',
                    text: text,
                    timestamp: Date.now(),
                    attachments: atts.length > 0 ? atts : undefined
                };
            });
            setMessages(convertedMessages);
        }
    } catch (e) {
        console.error("Failed to load history", e);
    }
  };

  const createSession = async (mode: AIWorkMode = 'general') => {
    const res = await fetch('/api/ai/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode })
    });
    const newSession = await res.json();
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      await fetch(`/api/ai/sessions/${id}`, { method: 'DELETE' });
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
          setCurrentSessionId(null);
          setMessages([]);
      }
  };

  // --- Messaging ---
  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if ((!textToSend.trim() && attachments.length === 0) || isLoading) return;

    // FIX: Lock history loading
    isSendingRef.current = true;
    setIsLoading(true);

    try {
        // Auto-create session if none
        let activeSessionId = currentSessionId;
        if (!activeSessionId) {
            try {
                const res = await fetch('/api/ai/sessions', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'general' }) });
                const newS = await res.json();
                setSessions(prev => [newS, ...prev]);
                activeSessionId = newS.id;
                setCurrentSessionId(newS.id);
            } catch (e) {
                console.error("Failed to create session", e);
                return;
            }
        }

        const tempAttachments = [...attachments];

        // User Message
        const userMsg: ChatMessage = {
          id: Date.now().toString(),
          role: 'user',
          text: textToSend,
          timestamp: Date.now(),
          attachments: tempAttachments
        };

        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setAttachments([]);

        // AI Placeholder
        const aiMsgId = (Date.now() + 1).toString();
        const aiMsgPlaceholder: ChatMessage = {
          id: aiMsgId,
          role: 'model',
          text: '',
          timestamp: Date.now() + 1,
          isThinking: true
        };
        setMessages(prev => [...prev, aiMsgPlaceholder]);

        try {
          const response = await fetch('/api/ai/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              sessionId: activeSessionId,
              message: textToSend,
              attachments: tempAttachments,
              model: model,
              lang: lang
            })
          });

          if (!response.body) throw new Error("No response");

          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let done = false;
          let accumulatedText = '';

          while (!done) {
            const { value, done: doneReading } = await reader.read();
            done = doneReading;
            const chunkValue = decoder.decode(value, { stream: !done });
            accumulatedText += chunkValue;

            setMessages(prev => prev.map(msg => 
              msg.id === aiMsgId 
                ? { ...msg, text: accumulatedText, isThinking: false } 
                : msg
            ));
          }

          setSessions(prev => prev.map(s => s.id === activeSessionId ? { ...s, lastMessageAt: Date.now(), preview: accumulatedText.substring(0, 50) } : s));

        } catch (error) {
          console.error(error);
          setMessages(prev => prev.map(msg => 
            msg.id === aiMsgId ? { ...msg, text: t.error, isThinking: false } : msg
          ));
        }
    } finally {
        setIsLoading(false);
        isSendingRef.current = false; // FIX: Unlock
        setTimeout(() => inputRef.current?.focus(), 100);
    }
  };

  // --- Attachments ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];
          const formData = new FormData();
          formData.append('image', file);

          try {
              const res = await fetch('/api/upload', { method: 'POST', body: formData });
              const data = await res.json();

              const newAtt: AIAttachment = {
                  id: data.id,
                  type: file.type.startsWith('image/') ? 'image' : 'file',
                  url: data.url,
                  filename: data.filename,
                  mimeType: data.mimeType || file.type
              };
              setAttachments(prev => [...prev, newAtt]);
          } catch (e) { console.error(e); alert("Upload Failed"); }
      }
  };

  // --- Voice Input (STT) ---
  const startRecording = async () => {
      try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          const mediaRecorder = new MediaRecorder(stream);
          mediaRecorderRef.current = mediaRecorder;
          const chunks: Blob[] = [];

          mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
          mediaRecorder.onstop = async () => {
              const blob = new Blob(chunks, { type: 'audio/webm' }); 
              const formData = new FormData();
              formData.append('audio', blob, 'voice_input.webm');

              setIsLoading(true); 
              try {
                  const res = await fetch('/api/ai/transcribe', { method: 'POST', headers: { 'api-key': 'internal' }, body: formData });
                  const data = await res.json();
                  if (data.text) {
                      handleSend(data.text); 
                  }
              } catch (e) { console.error(e); } finally { setIsLoading(false); }
          };

          mediaRecorder.start();
          setIsRecording(true);
      } catch (e) { alert("Mic Access Denied"); }
  };

  const stopRecording = () => {
      mediaRecorderRef.current?.stop();
      setIsRecording(false);
  };

  // --- TTS ---
  const playTTS = async (text: string) => {
      try {
          const cleanText = text.replace(/!\[.*?\]\(.*?\)/g, '');

          const res = await fetch('/api/ai/tts', { 
              method: 'POST', 
              headers: { 'Content-Type': 'application/json' }, 
              body: JSON.stringify({ text: cleanText }) 
          });
          const data = await res.json();
          if (data.audio) {
              const audio = new Audio(`data:audio/wav;base64,${data.audio}`);
              audio.play();
          }
      } catch (e) { console.error(e); }
  };

  // --- Render Helpers ---
  const renderMessageContent = (text: string) => {
      const parts = text.split(/(!\[.*?\]\(.*?\))/g);
      return parts.map((part, index) => {
          const imgMatch = part.match(/!\[(.*?)\]\((.*?)\)/);
          if (imgMatch) {
              const alt = imgMatch[1];
              const url = imgMatch[2];

              if (url.endsWith('.mp4') || alt.toLowerCase().includes('video')) {
                   return (
                      <div key={index} className="my-2 rounded-lg overflow-hidden border border-purple-600 shadow-lg relative group">
                          <video src={url} controls className="w-full max-h-64 bg-black/50" />
                          <div className="bg-purple-900/50 p-1 text-[10px] text-purple-300 font-code text-center">GENERATED_VEO_ASSET</div>
                      </div>
                   );
              }

              return (
                  <div key={index} className="my-2 rounded-lg overflow-hidden border border-slate-600 shadow-lg">
                      <img src={url} alt={alt} className="w-full max-h-64 object-contain bg-black/20" />
                      <div className="bg-slate-900/50 p-1 text-[10px] text-slate-500 font-code text-center">GENERATED_ASSET</div>
                  </div>
              );
          }
          return <span key={index}>{part}</span>;
      });
  };

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  const currentMeta = modelMeta[model] || { cost: 0, iq: 0, speed: 0 };

  return (
    <div className="flex h-full bg-[#020617] text-slate-200 overflow-hidden font-sans relative">

      {/* --- SIDEBAR --- */}
      <div className="w-16 md:w-64 flex flex-col bg-slate-900/50 border-r border-cyan-900/30 backdrop-blur-md z-20 transition-all">
        <div className="p-4 flex flex-col gap-2">
          <button onClick={() => createSession('general')} className="w-full flex items-center justify-center md:justify-start gap-3 px-3 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-tech text-xs tracking-widest uppercase shadow-lg transition-all clip-button">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden md:inline">{t.newChat}</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
           <div className="hidden md:block text-[10px] text-slate-500 font-code uppercase tracking-widest mb-2 px-2">{t.history}</div>
           <div className="space-y-1">
             {sessions.map(s => (
               <div key={s.id} onClick={() => setCurrentSessionId(s.id)} className={`group relative p-2 md:p-3 cursor-pointer border-l-2 transition-all ${currentSessionId === s.id ? 'bg-slate-800 border-cyan-500 text-cyan-100' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}>
                  <div className="flex justify-between items-center">
                      <div className="font-bold text-xs truncate w-full pr-6">{s.title || "Untitled Link"}</div>
                      <button onClick={(e) => deleteSession(s.id, e)} className="absolute right-2 opacity-0 group-hover:opacity-100 text-slate-600 hover:text-rose-500">×</button>
                  </div>
                  <div className="hidden md:block text-[10px] font-code truncate opacity-70 mt-1">{s.preview}</div>
                  <div className="hidden md:flex gap-2 mt-1">
                      <span className={`text-[8px] px-1 rounded border ${s.mode==='coder'?'border-purple-500 text-purple-400':s.mode==='analyst'?'border-emerald-500 text-emerald-400':'border-slate-600'}`}>{s.mode.toUpperCase()}</span>
                  </div>
               </div>
             ))}
           </div>
        </div>

        {/* Mode Selector */}
        <div className="p-2 border-t border-slate-800 hidden md:block">
            <div className="text-[10px] text-slate-500 font-code mb-2">{t.modes}</div>
            <div className="grid grid-cols-2 gap-1">
                {(['general', 'coder', 'analyst', 'creative'] as AIWorkMode[]).map(m => (
                    <button key={m} onClick={() => createSession(m)} className="text-[9px] border border-slate-700 p-1 hover:border-cyan-500 hover:text-cyan-400 uppercase transition-colors">
                        {modeLabels[m]} 
                    </button>
                ))}
            </div>
        </div>
      </div>

      {/* --- MAIN CHAT AREA --- */}
      <div className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

        {/* Header */}
        <div className="h-16 md:h-14 border-b border-cyan-900/30 bg-slate-900/80 backdrop-blur-md flex flex-col md:flex-row items-start md:items-center justify-between px-4 md:px-6 z-30 py-2 md:py-0 gap-2 md:gap-0">
           <div className="flex flex-col md:flex-row items-start md:items-center gap-2 md:gap-4 w-full md:w-auto">
              <div className="flex items-center gap-2">
                <span className="text-cyan-400 font-tech text-lg">{t.aiCoreTitle}</span>
                <span className="text-slate-600 font-thin">/</span>
                <select value={model} onChange={(e) => setModel(e.target.value as AIModelVersion)} className="bg-transparent text-xs font-code text-slate-300 focus:outline-none uppercase cursor-pointer hover:text-cyan-400 max-w-[200px] md:max-w-none">
                   <optgroup label="GOOGLE CLOUD" className="bg-slate-900 text-cyan-400">
                     <option value="gemini-3-flash-preview">{t.modelFlash}</option>
                     <option value="gemini-3-pro-preview">{t.modelPro}</option>
                     <option value="gemini-flash-latest">{t.modelFlashLatest}</option>
                     <option value="gemini-flash-lite-latest">{t.modelLite}</option>
                   </optgroup>
                   <optgroup label="OPENAI" className="bg-slate-900 text-green-400">
                     <option value="gpt-4o">GPT-4o (OMNI)</option>
                     <option value="gpt-4-turbo">GPT-4 TURBO</option>
                   </optgroup>
                   <optgroup label="LOCAL / OPEN SOURCE" className="bg-slate-900 text-amber-400">
                     <option value="llama-3-local">LLaMA 3 (LOCAL)</option>
                     <option value="stable-diffusion-xl">STABLE DIFFUSION (IMAGE)</option>
                   </optgroup>
                </select>
              </div>

              <div className="flex items-center gap-3 bg-black/20 px-2 py-1 rounded border border-white/5">
                 <div className="flex items-center gap-1">
                    <span className="text-[9px] text-slate-500 font-code uppercase">{t.cost}</span>
                    <div className="flex gap-0.5">
                       {[...Array(5)].map((_, i) => (
                          <div key={i} className={`w-1 h-2 rounded-sm ${i < currentMeta.cost ? 'bg-emerald-500' : 'bg-slate-800'}`}></div>
                       ))}
                    </div>
                 </div>
                 <div className="flex items-center gap-1">
                    <span className="text-[9px] text-slate-500 font-code uppercase">{t.iq}</span>
                    <div className="flex gap-0.5">
                       {[...Array(5)].map((_, i) => (
                          <div key={i} className={`w-1 h-2 rounded-sm ${i < currentMeta.iq ? 'bg-purple-500' : 'bg-slate-800'}`}></div>
                       ))}
                    </div>
                 </div>
                 {currentMeta.label && <span className="text-[9px] font-bold text-cyan-400 bg-cyan-900/30 px-1 rounded">{currentMeta.label}</span>}
              </div>
           </div>

           <div className="hidden md:flex gap-4 self-center">
              {currentSessionId && <span className="text-xs font-code text-slate-500 uppercase border px-2 py-0.5 border-slate-700 rounded-full">{sessions.find(s=>s.id===currentSessionId)?.mode} MODE</span>}
           </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-0 animate-[fadeIn_0.5s_ease-out_forwards]">
               <div className="w-20 h-20 mb-6 relative">
                  <div className="absolute inset-0 border-t-2 border-cyan-500 rounded-full animate-spin"></div>
                  <div className="absolute inset-2 border-b-2 border-purple-500 rounded-full animate-[spin_3s_linear_infinite]"></div>
                  <div className="absolute inset-0 flex items-center justify-center font-tech text-2xl text-white">AI</div>
               </div>
               <div className="text-slate-500 font-code text-sm uppercase">{t.emptyState}</div>
            </div>
          ) : (
            <div className="max-w-4xl mx-auto space-y-8">
               {messages.map((msg) => (
                 <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-8 h-8 flex-shrink-0 flex items-center justify-center rounded-sm border ${msg.role === 'user' ? 'bg-cyan-900/20 border-cyan-500/50 text-cyan-400' : 'bg-purple-900/20 border-purple-500/50 text-purple-400'}`}>
                       {msg.role === 'user' ? t.user : t.ai}
                    </div>

                    <div className={`flex flex-col max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                       {msg.attachments && msg.attachments.length > 0 && (
                           <div className="flex flex-wrap gap-2 mb-2 justify-end">
                               {msg.attachments.map(att => (
                                   <div key={att.id} className="relative group border border-slate-700 bg-slate-900 rounded overflow-hidden w-24 h-24 flex items-center justify-center">
                                       {att.type === 'image' ? (
                                           <img src={att.url} className="w-full h-full object-cover" />
                                       ) : (
                                           <div className="text-[9px] text-center p-1 text-slate-400 break-all">{att.filename}</div>
                                       )}
                                   </div>
                               ))}
                           </div>
                       )}

                       <div className={`p-4 text-sm font-sans leading-relaxed shadow-lg whitespace-pre-wrap ${msg.role === 'user' ? 'bg-cyan-950/30 border border-cyan-500/20 text-cyan-100 rounded-bl-xl' : 'bg-slate-900/80 border border-slate-700 text-slate-300 rounded-br-xl'}`}>
                          {msg.isThinking ? <span className="animate-pulse text-purple-400">{t.processing}</span> : renderMessageContent(msg.text)}
                       </div>

                       {msg.role === 'model' && !msg.isThinking && (
                           <button onClick={() => playTTS(msg.text)} className="mt-1 text-[10px] text-slate-600 hover:text-cyan-400 flex items-center gap-1 cursor-pointer transition-colors">
                               <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                               {t.tts}
                           </button>
                       )}
                    </div>
                 </div>
               ))}
               <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 bg-slate-900/90 backdrop-blur-xl border-t border-cyan-900/30 relative z-30">
           {attachments.length > 0 && (
               <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
                   <span className="text-xs text-cyan-500 font-code self-center mr-2">{t.attach}</span>
                   {attachments.map((att, i) => (
                       <div key={i} className="relative bg-slate-800 border border-slate-600 rounded p-1 w-12 h-12 flex items-center justify-center shrink-0">
                           {att.type==='image' ? <img src={att.url} className="w-full h-full object-cover opacity-70" /> : <span className="text-[8px] text-slate-400">FILE</span>}
                           <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-[10px] flex items-center justify-center">×</button>
                       </div>
                   ))}
               </div>
           )}

           <div className="max-w-4xl mx-auto flex gap-3 items-end">
              <div className="flex gap-2 pb-2">
                  <button onClick={() => fileInputRef.current?.click()} className="text-slate-500 hover:text-cyan-400 p-2 border border-transparent hover:border-slate-700 rounded transition-all">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

                  <button 
                    onMouseDown={startRecording} 
                    onMouseUp={stopRecording} 
                    className={`p-2 rounded border transition-all ${isRecording ? 'bg-red-900/50 text-red-500 border-red-500 animate-pulse' : 'text-slate-500 hover:text-cyan-400 border-transparent hover:border-slate-700'}`}
                  >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                  </button>
              </div>

              <div className="relative flex-1 group">
                 <div className="absolute -top-1 -left-1 w-2 h-2 border-t border-l border-cyan-500/50"></div>
                 <div className="absolute -bottom-1 -right-1 w-2 h-2 border-b border-r border-cyan-500/50"></div>

                 <textarea
                   ref={inputRef}
                   value={input}
                   onChange={(e) => setInput(e.target.value)}
                   onKeyDown={(e) => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                   placeholder={isRecording ? t.listening : t.placeholder}
                   className="w-full bg-black/60 border border-slate-700 text-white p-3 pr-10 focus:outline-none focus:border-cyan-500/50 transition-all font-sans resize-none custom-scrollbar max-h-32 min-h-[48px] rounded-none"
                   rows={1}
                 />
              </div>

              <button 
                onClick={() => handleSend()}
                disabled={isLoading || (!input.trim() && attachments.length===0)}
                className={`p-3 mb-1 bg-cyan-900/20 border border-cyan-500/30 text-cyan-400 hover:bg-cyan-600 hover:text-white transition-all ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Language, ChatMessage, AIModelVersion, ChatSession, AIWorkMode, AIAttachment } from '../types';

interface AICoreProps {
  lang: Language;
}

export const AICore: React.FC<AICoreProps> = ({ lang }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [model, setModel] = useState<AIModelVersion>('gemini-3-flash-preview');

  // Attachments & Audio
  const [attachments, setAttachments] = useState<AIAttachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // FIX: Guard to prevent history loading from clearing active messages during a live chat stream
  const isSendingRef = useRef(false);

  const t = {
    en: {
      aiCoreTitle: "AI_CORE",
      newChat: "NEW SESSION",
      placeholder: "Broadcast message to core...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      modelFlashLatest: "GEMINI FLASH",
      modelLite: "GEMINI LITE",
      history: "SESSIONS",
      modes: "WORK MODE",
      modeGen: "GENERAL",
      modeCode: "ENGINEER",
      modeData: "ANALYST",
      modeCreate: "CREATIVE",
      upload: "UPLOAD FILE",
      voice: "VOICE",
      listening: "LISTENING...",
      attach: "ATTACHED RES:",
      play: "PLAY",
      tts: "READ ALOUD",
      emptyState: "AWAITING INPUT STREAM...",
      processing: "PROCESSING...",
      error: "Error: Neural Link Failed.",
      user: "U",
      ai: "AI",
      cost: "COST",
      iq: "IQ",
      speed: "SPD",
      fileError: "ERROR: UNSUPPORTED FORMAT",
      fileHint: "SUPPORTED: IMG, VIDEO, AUDIO, PDF, CODE/TXT"
    },
    zh: {
      aiCoreTitle: "AI 核心",
      newChat: "新建会话",
      placeholder: "输入指令或提问...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      modelFlashLatest: "GEMINI FLASH",
      modelLite: "GEMINI LITE",
      history: "历史会话",
      modes: "工作模式",
      modeGen: "通用助手",
      modeCode: "赛博工程师",
      modeData: "数据分析师",
      modeCreate: "创意总监",
      upload: "上传文件",
      voice: "语音输入",
      listening: "正在聆听...",
      attach: "已挂载资源:",
      play: "播放",
      tts: "朗读",
      emptyState: "等待输入信号...",
      processing: "计算中...",
      error: "错误：神经连接中断。",
      user: "我",
      ai: "AI",
      cost: "成本",
      iq: "智商",
      speed: "速度",
      fileError: "错误：不支持的文件格式",
      fileHint: "支持格式：图片、视频、音频、PDF、代码/文本"
    }
  }[lang];

  const modeLabels: Record<string, string> = {
      general: t.modeGen,
      coder: t.modeCode,
      analyst: t.modeData,
      creative: t.modeCreate
  };

  // Model Metadata for UI
  const modelMeta: Record<string, { cost: number; iq: number; speed: number; label?: string }> = {
      'gemini-flash-lite-latest': { cost: 1, iq: 3, speed: 5, label: "VALUE" },
      'gemini-flash-latest':      { cost: 2, iq: 4, speed: 5, label: "FAST" },
      'gemini-3-flash-preview':   { cost: 3, iq: 4, speed: 4, label: "BALANCED" },
      'gemini-3-pro-preview':     { cost: 5, iq: 5, speed: 3, label: "MAX INTEL" },
      'gpt-4o':                   { cost: 5, iq: 5, speed: 4, label: "OPENAI" },
      'gpt-4-turbo':              { cost: 4, iq: 5, speed: 4, label: "LEGACY" },
      'llama-3-local':            { cost: 0, iq: 3, speed: 5, label: "LOCAL" },
      'stable-diffusion-xl':      { cost: 0, iq: 0, speed: 2, label: "IMAGE ONLY" }
  };

  // --- Session Management ---
  useEffect(() => {
    fetchSessions();
  }, []);

  // Sync History when session ID changes
  useEffect(() => {
      // FIX: Only load history if we are NOT currently sending a message
      if (currentSessionId && !isSendingRef.current) {
          loadSessionHistory(currentSessionId);
      }
  }, [currentSessionId]);

  const fetchSessions = async () => {
    try {
      const res = await fetch('/api/ai/sessions');
      const data = await res.json();
      setSessions(data);
    } catch (e) {
      console.error(e);
    }
  };

  const loadSessionHistory = async (id: string) => {
    setMessages([]); 
    try {
        const res = await fetch(`/api/ai/sessions/${id}`);
        if (!res.ok) return;
        const sessionData = await res.json();

        if (sessionData.history && Array.isArray(sessionData.history)) {
            const convertedMessages: ChatMessage[] = sessionData.history.map((h: any, index: number) => {
                let text = "";
                const atts: AIAttachment[] = [];

                if (h.parts) {
                    h.parts.forEach((p: any) => {
                        if (p.text) text += p.text;
                        if (p.inlineData) {
                            atts.push({
                                id: `hist-att-${index}-${Date.now()}-${Math.random()}`,
                                type: 'image',
                                url: `data:${p.inlineData.mimeType};base64,${p.inlineData.data}`,
                                filename: 'history_asset',
                                mimeType: p.inlineData.mimeType,
                                data: p.inlineData.data
                            });
                        }
                    });
                }

                return {
                    id: `msg-hist-${index}-${Date.now()}`,
                    role: h.role === 'model' ? 'model' : 'user',
                    text: text,
                    timestamp: Date.now(),
                    attachments: atts.length > 0 ? atts : undefined
                };
            });
            setMessages(convertedMessages);
        }
    } catch (e) {
        console.error("Failed to load history", e);
    }
  };

  const createSession = async (mode: AIWorkMode = 'general') => {
    const res = await fetch('/api/ai/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode })
    });
    const newSession = await res.json();
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      await fetch(`/api/ai/sessions/${id}`, { method: 'DELETE' });
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
          setCurrentSessionId(null);
          setMessages([]);
      }
  };

  // --- Messaging ---
  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if ((!textToSend.trim() && attachments.length === 0) || isLoading) return;

    // FIX: Lock history loading
    isSendingRef.current = true;
    setIsLoading(true);

    try {
        // Auto-create session if none
        let activeSessionId = currentSessionId;
        if (!activeSessionId) {
            try {
                const res = await fetch('/api/ai/sessions', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'general' }) });
                const newS = await res.json();
                setSessions(prev => [newS, ...prev]);
                activeSessionId = newS.id;
                setCurrentSessionId(newS.id);
            } catch (e) {
                console.error("Failed to create session", e);
                return;
            }
        }

        const tempAttachments = [...attachments];

        // User Message
        const userMsg: ChatMessage = {
          id: Date.now().toString(),
          role: 'user',
          text: textToSend,
          timestamp: Date.now(),
          attachments: tempAttachments
        };

        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setAttachments([]);

        // AI Placeholder
        const aiMsgId = (Date.now() + 1).toString();
        const aiMsgPlaceholder: ChatMessage = {
          id: aiMsgId,
          role: 'model',
          text: '',
          timestamp: Date.now() + 1,
          isThinking: true
        };
        setMessages(prev => [...prev, aiMsgPlaceholder]);

        try {
          const response = await fetch('/api/ai/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              sessionId: activeSessionId,
              message: textToSend,
              attachments: tempAttachments,
              model: model,
              lang: lang
            })
          });

          if (!response.body) throw new Error("No response");

          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let done = false;
          let accumulatedText = '';

          while (!done) {
            const { value, done: doneReading } = await reader.read();
            done = doneReading;
            const chunkValue = decoder.decode(value, { stream: !done });
            accumulatedText += chunkValue;

            setMessages(prev => prev.map(msg => 
              msg.id === aiMsgId 
                ? { ...msg, text: accumulatedText, isThinking: false } 
                : msg
            ));
          }

          setSessions(prev => prev.map(s => s.id === activeSessionId ? { ...s, lastMessageAt: Date.now(), preview: accumulatedText.substring(0, 50) } : s));

        } catch (error) {
          console.error(error);
          setMessages(prev => prev.map(msg => 
            msg.id === aiMsgId ? { ...msg, text: t.error, isThinking: false } : msg
          ));
        }
    } finally {
        setIsLoading(false);
        isSendingRef.current = false; // FIX: Unlock
        setTimeout(() => inputRef.current?.focus(), 100);
    }
  };

  // --- Attachments ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];

          // Validation
          const validTypes = ['image/', 'video/', 'audio/', 'text/', 'application/pdf'];
          const validExts = ['.js', '.ts', '.jsx', '.tsx', '.py', '.java', '.c', '.cpp', '.h', '.cs', '.go', '.rs', '.php', '.html', '.css', '.json', '.xml', '.yaml', '.yml', '.md', '.sql'];

          const isValidType = validTypes.some(t => file.type.startsWith(t));
          const isValidExt = validExts.some(ext => file.name.toLowerCase().endsWith(ext));

          if (!isValidType && !isValidExt) {
              alert(`${t.fileError}\n${t.fileHint}`);
              if (fileInputRef.current) fileInputRef.current.value = '';
              return;
          }

          const formData = new FormData();
          formData.append('image', file);

          try {
              const res = await fetch('/api/upload', { method: 'POST', body: formData });
              const data = await res.json();

              const newAtt: AIAttachment = {
                  id: data.id,
                  type: file.type.startsWith('image/') ? 'image' : 'file',
                  url: data.url,
                  filename: data.filename,
                  mimeType: data.mimeType || file.type
              };
              setAttachments(prev => [...prev, newAtt]);
          } catch (e) { console.error(e); alert("Upload Failed"); }
      }
  };

  // --- Voice Input (STT) ---
  const startRecording = async () => {
      try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          const mediaRecorder = new MediaRecorder(stream);
          mediaRecorderRef.current = mediaRecorder;
          const chunks: Blob[] = [];

          mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
          mediaRecorder.onstop = async () => {
              const blob = new Blob(chunks, { type: 'audio/webm' }); 
              const formData = new FormData();
              formData.append('audio', blob, 'voice_input.webm');

              setIsLoading(true); 
              try {
                  const res = await fetch('/api/ai/transcribe', { method: 'POST', headers: { 'api-key': 'internal' }, body: formData });
                  const data = await res.json();
                  if (data.text) {
                      handleSend(data.text); 
                  }
              } catch (e) { console.error(e); } finally { setIsLoading(false); }
          };

          mediaRecorder.start();
          setIsRecording(true);
      } catch (e) { alert("Mic Access Denied"); }
  };

  const stopRecording = () => {
      mediaRecorderRef.current?.stop();
      setIsRecording(false);
  };

  // --- TTS ---
  const playTTS = async (text: string) => {
      try {
          const cleanText = text.replace(/!\[.*?\]\(.*?\)/g, '');

          const res = await fetch('/api/ai/tts', { 
              method: 'POST', 
              headers: { 'Content-Type': 'application/json' }, 
              body: JSON.stringify({ text: cleanText }) 
          });
          const data = await res.json();
          if (data.audio) {
              const audio = new Audio(`data:audio/wav;base64,${data.audio}`);
              audio.play();
          }
      } catch (e) { console.error(e); }
  };

  // --- Render Helpers ---
  const renderMessageContent = (text: string) => {
      const parts = text.split(/(!\[.*?\]\(.*?\))/g);
      return parts.map((part, index) => {
          const imgMatch = part.match(/!\[(.*?)\]\((.*?)\)/);
          if (imgMatch) {
              const alt = imgMatch[1];
              const url = imgMatch[2];

              if (url.endsWith('.mp4') || alt.toLowerCase().includes('video')) {
                   return (
                      <div key={index} className="my-2 rounded-lg overflow-hidden border border-purple-600 shadow-lg relative group">
                          <video src={url} controls className="w-full max-h-64 bg-black/50" />
                          <div className="bg-purple-900/50 p-1 text-[10px] text-purple-300 font-code text-center">GENERATED_VEO_ASSET</div>
                      </div>
                   );
              }

              return (
                  <div key={index} className="my-2 rounded-lg overflow-hidden border border-slate-600 shadow-lg">
                      <img src={url} alt={alt} className="w-full max-h-64 object-contain bg-black/20" />
                      <div className="bg-slate-900/50 p-1 text-[10px] text-slate-500 font-code text-center">GENERATED_ASSET</div>
                  </div>
              );
          }
          return <span key={index}>{part}</span>;
      });
  };

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  const currentMeta = modelMeta[model] || { cost: 0, iq: 0, speed: 0 };

  return (
    <div className="flex h-full bg-[#020617] text-slate-200 overflow-hidden font-sans relative">

      {/* --- SIDEBAR --- */}
      <div className="w-16 md:w-64 flex flex-col bg-slate-900/50 border-r border-cyan-900/30 backdrop-blur-md z-20 transition-all">
        <div className="p-4 flex flex-col gap-2">
          <button onClick={() => createSession('general')} className="w-full flex items-center justify-center md:justify-start gap-3 px-3 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-tech text-xs tracking-widest uppercase shadow-lg transition-all clip-button">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden md:inline">{t.newChat}</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
           <div className="hidden md:block text-[10px] text-slate-500 font-code uppercase tracking-widest mb-2 px-2">{t.history}</div>
           <div className="space-y-1">
             {sessions.map(s => (
               <div key={s.id} onClick={() => setCurrentSessionId(s.id)} className={`group relative p-2 md:p-3 cursor-pointer border-l-2 transition-all ${currentSessionId === s.id ? 'bg-slate-800 border-cyan-500 text-cyan-100' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}>
                  <div className="flex justify-between items-center">
                      <div className="font-bold text-xs truncate w-full pr-6">{s.title || "Untitled Link"}</div>
                      <button onClick={(e) => deleteSession(s.id, e)} className="absolute right-2 opacity-0 group-hover:opacity-100 text-slate-600 hover:text-rose-500">×</button>
                  </div>
                  <div className="hidden md:block text-[10px] font-code truncate opacity-70 mt-1">{s.preview}</div>
                  <div className="hidden md:flex gap-2 mt-1">
                      <span className={`text-[8px] px-1 rounded border ${s.mode==='coder'?'border-purple-500 text-purple-400':s.mode==='analyst'?'border-emerald-500 text-emerald-400':'border-slate-600'}`}>{s.mode.toUpperCase()}</span>
                  </div>
               </div>
             ))}
           </div>
        </div>

        {/* Mode Selector */}
        <div className="p-2 border-t border-slate-800 hidden md:block">
            <div className="text-[10px] text-slate-500 font-code mb-2">{t.modes}</div>
            <div className="grid grid-cols-2 gap-1">
                {(['general', 'coder', 'analyst', 'creative'] as AIWorkMode[]).map(m => (
                    <button key={m} onClick={() => createSession(m)} className="text-[9px] border border-slate-700 p-1 hover:border-cyan-500 hover:text-cyan-400 uppercase transition-colors">
                        {modeLabels[m]} 
                    </button>
                ))}
            </div>
        </div>
      </div>

      {/* --- MAIN CHAT AREA --- */}
      <div className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

        {/* Header */}
        <div className="h-16 md:h-14 border-b border-cyan-900/30 bg-slate-900/80 backdrop-blur-md flex flex-col md:flex-row items-start md:items-center justify-between px-4 md:px-6 z-30 py-2 md:py-0 gap-2 md:gap-0">
           <div className="flex flex-col md:flex-row items-start md:items-center gap-2 md:gap-4 w-full md:w-auto">
              <div className="flex items-center gap-2">
                <span className="text-cyan-400 font-tech text-lg">{t.aiCoreTitle}</span>
                <span className="text-slate-600 font-thin">/</span>
                <select value={model} onChange={(e) => setModel(e.target.value as AIModelVersion)} className="bg-transparent text-xs font-code text-slate-300 focus:outline-none uppercase cursor-pointer hover:text-cyan-400 max-w-[200px] md:max-w-none">
                   <optgroup label="GOOGLE CLOUD" className="bg-slate-900 text-cyan-400">
                     <option value="gemini-3-flash-preview">{t.modelFlash}</option>
                     <option value="gemini-3-pro-preview">{t.modelPro}</option>
                     <option value="gemini-flash-latest">{t.modelFlashLatest}</option>
                     <option value="gemini-flash-lite-latest">{t.modelLite}</option>
                   </optgroup>
                   <optgroup label="OPENAI" className="bg-slate-900 text-green-400">
                     <option value="gpt-4o">GPT-4o (OMNI)</option>
                     <option value="gpt-4-turbo">GPT-4 TURBO</option>
                   </optgroup>
                   <optgroup label="LOCAL / OPEN SOURCE" className="bg-slate-900 text-amber-400">
                     <option value="llama-3-local">LLaMA 3 (LOCAL)</option>
                     <option value="stable-diffusion-xl">STABLE DIFFUSION (IMAGE)</option>
                   </optgroup>
                </select>
              </div>

              <div className="flex items-center gap-3 bg-black/20 px-2 py-1 rounded border border-white/5">
                 <div className="flex items-center gap-1">
                    <span className="text-[9px] text-slate-500 font-code uppercase">{t.cost}</span>
                    <div className="flex gap-0.5">
                       {[...Array(5)].map((_, i) => (
                          <div key={i} className={`w-1 h-2 rounded-sm ${i < currentMeta.cost ? 'bg-emerald-500' : 'bg-slate-800'}`}></div>
                       ))}
                    </div>
                 </div>
                 <div className="flex items-center gap-1">
                    <span className="text-[9px] text-slate-500 font-code uppercase">{t.iq}</span>
                    <div className="flex gap-0.5">
                       {[...Array(5)].map((_, i) => (
                          <div key={i} className={`w-1 h-2 rounded-sm ${i < currentMeta.iq ? 'bg-purple-500' : 'bg-slate-800'}`}></div>
                       ))}
                    </div>
                 </div>
                 {currentMeta.label && <span className="text-[9px] font-bold text-cyan-400 bg-cyan-900/30 px-1 rounded">{currentMeta.label}</span>}
              </div>
           </div>

           <div className="hidden md:flex gap-4 self-center">
              {currentSessionId && <span className="text-xs font-code text-slate-500 uppercase border px-2 py-0.5 border-slate-700 rounded-full">{sessions.find(s=>s.id===currentSessionId)?.mode} MODE</span>}
           </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-0 animate-[fadeIn_0.5s_ease-out_forwards]">
               <div className="w-20 h-20 mb-6 relative">
                  <div className="absolute inset-0 border-t-2 border-cyan-500 rounded-full animate-spin"></div>
                  <div className="absolute inset-2 border-b-2 border-purple-500 rounded-full animate-[spin_3s_linear_infinite]"></div>
                  <div className="absolute inset-0 flex items-center justify-center font-tech text-2xl text-white">AI</div>
               </div>
               <div className="text-slate-500 font-code text-sm uppercase">{t.emptyState}</div>
            </div>
          ) : (
            <div className="max-w-4xl mx-auto space-y-8">
               {messages.map((msg) => (
                 <div key={msg.id} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-8 h-8 flex-shrink-0 flex items-center justify-center rounded-sm border ${msg.role === 'user' ? 'bg-cyan-900/20 border-cyan-500/50 text-cyan-400' : 'bg-purple-900/20 border-purple-500/50 text-purple-400'}`}>
                       {msg.role === 'user' ? t.user : t.ai}
                    </div>

                    <div className={`flex flex-col max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                       {msg.attachments && msg.attachments.length > 0 && (
                           <div className="flex flex-wrap gap-2 mb-2 justify-end">
                               {msg.attachments.map(att => (
                                   <div key={att.id} className="relative group border border-slate-700 bg-slate-900 rounded overflow-hidden w-24 h-24 flex items-center justify-center">
                                       {att.type === 'image' ? (
                                           <img src={att.url} className="w-full h-full object-cover" />
                                       ) : (
                                           <div className="text-[9px] text-center p-1 text-slate-400 break-all">{att.filename}</div>
                                       )}
                                   </div>
                               ))}
                           </div>
                       )}

                       <div className={`p-4 text-sm font-sans leading-relaxed shadow-lg whitespace-pre-wrap ${msg.role === 'user' ? 'bg-cyan-950/30 border border-cyan-500/20 text-cyan-100 rounded-bl-xl' : 'bg-slate-900/80 border border-slate-700 text-slate-300 rounded-br-xl'}`}>
                          {msg.isThinking ? <span className="animate-pulse text-purple-400">{t.processing}</span> : renderMessageContent(msg.text)}
                       </div>

                       {msg.role === 'model' && !msg.isThinking && (
                           <button onClick={() => playTTS(msg.text)} className="mt-1 text-[10px] text-slate-600 hover:text-cyan-400 flex items-center gap-1 cursor-pointer transition-colors">
                               <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                               {t.tts}
                           </button>
                       )}
                    </div>
                 </div>
               ))}
               <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 bg-slate-900/90 backdrop-blur-xl border-t border-cyan-900/30 relative z-30">
           {attachments.length > 0 && (
               <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
                   <span className="text-xs text-cyan-500 font-code self-center mr-2">{t.attach}</span>
                   {attachments.map((att, i) => (
                       <div key={i} className="relative bg-slate-800 border border-slate-600 rounded p-1 w-12 h-12 flex items-center justify-center shrink-0">
                           {att.type==='image' ? <img src={att.url} className="w-full h-full object-cover opacity-70" /> : <span className="text-[8px] text-slate-400">FILE</span>}
                           <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-[10px] flex items-center justify-center">×</button>
                       </div>
                   ))}
               </div>
           )}

           <div className="max-w-4xl mx-auto flex gap-3 items-end">
              <div className="flex gap-2 pb-2">
                  <button onClick={() => fileInputRef.current?.click()} className="text-slate-500 hover:text-cyan-400 p-2 border border-transparent hover:border-slate-700 rounded transition-all">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

                  <button 
                    onMouseDown={startRecording} 
                    onMouseUp={stopRecording} 
                    className={`p-2 rounded border transition-all ${isRecording ? 'bg-red-900/50 text-red-500 border-red-500 animate-pulse' : 'text-slate-500 hover:text-cyan-400 border-transparent hover:border-slate-700'}`}
                  >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                  </button>
              </div>

              <div className="relative flex-1 group">
                 <div className="absolute -top-1 -left-1 w-2 h-2 border-t border-l border-cyan-500/50"></div>
                 <div className="absolute -bottom-1 -right-1 w-2 h-2 border-b border-r border-cyan-500/50"></div>

                 <textarea
                   ref={inputRef}
                   value={input}
                   onChange={(e) => setInput(e.target.value)}
                   onKeyDown={(e) => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                   placeholder={isRecording ? t.listening : t.placeholder}
                   className="w-full bg-black/60 border border-slate-700 text-white p-3 pr-10 focus:outline-none focus:border-cyan-500/50 transition-all font-sans resize-none custom-scrollbar max-h-32 min-h-[48px] rounded-none"
                   rows={1}
                 />
              </div>

              <button 
                onClick={() => handleSend()}
                disabled={isLoading || (!input.trim() && attachments.length===0)}
                className={`p-3 mb-1 bg-cyan-900/20 border border-cyan-500/30 text-cyan-400 hover:bg-cyan-600 hover:text-white transition-all ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Language, ChatMessage, AIModelVersion, ChatSession, AIWorkMode, AIAttachment } from '../types';

interface AICoreProps {
  lang: Language;
}

export const AICore: React.FC<AICoreProps> = ({ lang }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [model, setModel] = useState<AIModelVersion>('gemini-3-flash-preview');

  // Attachments & Audio
  const [attachments, setAttachments] = useState<AIAttachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // FIX: Guard to prevent history loading from clearing active messages during a live chat stream
  const isSendingRef = useRef(false);

  // Custom Alert State
  const [alertModal, setAlertModal] = useState<{show: boolean, title: string, message: string, type: 'error' | 'info'}>({
    show: false, title: '', message: '', type: 'error'
  });

  const showAlert = (title: string, message: string, type: 'error' | 'info' = 'error') => {
      setAlertModal({ show: true, title, message, type });
  };

  const t = {
    en: {
      aiCoreTitle: "AI_CORE",
      newChat: "NEW SESSION",
      placeholder: "Broadcast message to core...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      modelFlashLatest: "GEMINI FLASH",
      modelLite: "GEMINI LITE",
      history: "SESSIONS",
      modes: "WORK MODE",
      modeGen: "GENERAL",
      modeCode: "ENGINEER",
      modeData: "ANALYST",
      modeCreate: "CREATIVE",
      upload: "UPLOAD FILE",
      voice: "VOICE",
      listening: "LISTENING...",
      attach: "ATTACHED RES:",
      play: "PLAY",
      tts: "READ ALOUD",
      emptyState: "AWAITING INPUT STREAM...",
      processing: "PROCESSING...",
      error: "Error: Neural Link Failed.",
      user: "U",
      ai: "AI",
      cost: "COST",
      iq: "IQ",
      speed: "SPD",
      fileError: "UNSUPPORTED FORMAT",
      fileHint: "SUPPORTED: IMG, VIDEO, AUDIO, PDF, CODE/TXT",
      micError: "MIC ACCESS DENIED",
      micHint: "Please enable microphone permissions in your browser settings.",
      ack: "ACKNOWLEDGE",
      uploadFail: "UPLOAD FAILED"
    },
    zh: {
      aiCoreTitle: "AI 核心",
      newChat: "新建会话",
      placeholder: "输入指令或提问...",
      modelFlash: "GEMINI 3 FLASH",
      modelPro: "GEMINI 3 PRO",
      modelFlashLatest: "GEMINI FLASH",
      modelLite: "GEMINI LITE",
      history: "历史会话",
      modes: "工作模式",
      modeGen: "通用助手",
      modeCode: "赛博工程师",
      modeData: "数据分析师",
      modeCreate: "创意总监",
      upload: "上传文件",
      voice: "语音输入",
      listening: "正在聆听...",
      attach: "已挂载资源:",
      play: "播放",
      tts: "朗读",
      emptyState: "等待输入信号...",
      processing: "计算中...",
      error: "错误：神经连接中断。",
      user: "我",
      ai: "AI",
      cost: "成本",
      iq: "智商",
      speed: "速度",
      fileError: "不支持的文件格式",
      fileHint: "支持格式：图片、视频、音频、PDF、代码/文本",
      micError: "麦克风访问被拒绝",
      micHint: "请在浏览器设置中允许使用麦克风。",
      ack: "确认",
      uploadFail: "上传失败"
    }
  }[lang];

  const modeLabels: Record<string, string> = {
      general: t.modeGen,
      coder: t.modeCode,
      analyst: t.modeData,
      creative: t.modeCreate
  };

  // Model Metadata for UI
  const modelMeta: Record<string, { cost: number; iq: number; speed: number; label?: string }> = {
      'gemini-flash-lite-latest': { cost: 1, iq: 3, speed: 5, label: "VALUE" },
      'gemini-flash-latest':      { cost: 2, iq: 4, speed: 5, label: "FAST" },
      'gemini-3-flash-preview':   { cost: 3, iq: 4, speed: 4, label: "BALANCED" },
      'gemini-3-pro-preview':     { cost: 5, iq: 5, speed: 3, label: "MAX INTEL" },
      'gpt-4o':                   { cost: 5, iq: 5, speed: 4, label: "OPENAI" },
      'gpt-4-turbo':              { cost: 4, iq: 5, speed: 4, label: "LEGACY" },
      'llama-3-local':            { cost: 0, iq: 3, speed: 5, label: "LOCAL" },
      'stable-diffusion-xl':      { cost: 0, iq: 0, speed: 2, label: "IMAGE ONLY" }
  };

  // --- Session Management ---
  useEffect(() => {
    fetchSessions();
  }, []);

  // Sync History when session ID changes
  useEffect(() => {
      // FIX: Only load history if we are NOT currently sending a message
      if (currentSessionId && !isSendingRef.current) {
          loadSessionHistory(currentSessionId);
      }
  }, [currentSessionId]);

  const fetchSessions = async () => {
    try {
      const res = await fetch('/api/ai/sessions');
      const data = await res.json();
      setSessions(data);
    } catch (e) {
      console.error(e);
    }
  };

  const loadSessionHistory = async (id: string) => {
    setMessages([]); 
    try {
        const res = await fetch(`/api/ai/sessions/${id}`);
        if (!res.ok) return;
        const sessionData = await res.json();

        if (sessionData.history && Array.isArray(sessionData.history)) {
            const convertedMessages: ChatMessage[] = sessionData.history.map((h: any, index: number) => {
                let text = "";
                const atts: AIAttachment[] = [];

                if (h.parts) {
                    h.parts.forEach((p: any) => {
                        if (p.text) text += p.text;
                        if (p.inlineData) {
                            atts.push({
                                id: `hist-att-${index}-${Date.now()}-${Math.random()}`,
                                type: 'image',
                                url: `data:${p.inlineData.mimeType};base64,${p.inlineData.data}`,
                                filename: 'history_asset',
                                mimeType: p.inlineData.mimeType,
                                data: p.inlineData.data
                            });
                        }
                    });
                }

                return {
                    id: `msg-hist-${index}-${Date.now()}`,
                    role: h.role === 'model' ? 'model' : 'user',
                    text: text,
                    timestamp: Date.now(),
                    attachments: atts.length > 0 ? atts : undefined
                };
            });
            setMessages(convertedMessages);
        }
    } catch (e) {
        console.error("Failed to load history", e);
    }
  };

  const createSession = async (mode: AIWorkMode = 'general') => {
    const res = await fetch('/api/ai/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode })
    });
    const newSession = await res.json();
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
  };

  const deleteSession = async (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      await fetch(`/api/ai/sessions/${id}`, { method: 'DELETE' });
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
          setCurrentSessionId(null);
          setMessages([]);
      }
  };

  // --- Messaging ---
  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if ((!textToSend.trim() && attachments.length === 0) || isLoading) return;

    // FIX: Lock history loading
    isSendingRef.current = true;
    setIsLoading(true);

    try {
        // Auto-create session if none
        let activeSessionId = currentSessionId;
        if (!activeSessionId) {
            try {
                const res = await fetch('/api/ai/sessions', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: 'general' }) });
                const newS = await res.json();
                setSessions(prev => [newS, ...prev]);
                activeSessionId = newS.id;
                setCurrentSessionId(newS.id);
            } catch (e) {
                console.error("Failed to create session", e);
                return;
            }
        }

        const tempAttachments = [...attachments];

        // User Message
        const userMsg: ChatMessage = {
          id: Date.now().toString(),
          role: 'user',
          text: textToSend,
          timestamp: Date.now(),
          attachments: tempAttachments
        };

        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setAttachments([]);

        // AI Placeholder
        const aiMsgId = (Date.now() + 1).toString();
        const aiMsgPlaceholder: ChatMessage = {
          id: aiMsgId,
          role: 'model',
          text: '',
          timestamp: Date.now() + 1,
          isThinking: true
        };
        setMessages(prev => [...prev, aiMsgPlaceholder]);

        try {
          const response = await fetch('/api/ai/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              sessionId: activeSessionId,
              message: textToSend,
              attachments: tempAttachments,
              model: model,
              lang: lang
            })
          });

          if (!response.body) throw new Error("No response");

          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let done = false;
          let accumulatedText = '';

          while (!done) {
            const { value, done: doneReading } = await reader.read();
            done = doneReading;
            const chunkValue = decoder.decode(value, { stream: !done });
            accumulatedText += chunkValue;

            setMessages(prev => prev.map(msg => 
              msg.id === aiMsgId 
                ? { ...msg, text: accumulatedText, isThinking: false } 
                : msg
            ));
          }

          setSessions(prev => prev.map(s => s.id === activeSessionId ? { ...s, lastMessageAt: Date.now(), preview: accumulatedText.substring(0, 50) } : s));

        } catch (error) {
          console.error(error);
          setMessages(prev => prev.map(msg => 
            msg.id === aiMsgId ? { ...msg, text: t.error, isThinking: false } : msg
          ));
        }
    } finally {
        setIsLoading(false);
        isSendingRef.current = false; // FIX: Unlock
        setTimeout(() => inputRef.current?.focus(), 100);
    }
  };

  // --- Attachments ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];

          // Validation
          const validTypes = ['image/', 'video/', 'audio/', 'text/', 'application/pdf'];
          const validExts = ['.js', '.ts', '.jsx', '.tsx', '.py', '.java', '.c', '.cpp', '.h', '.cs', '.go', '.rs', '.php', '.html', '.css', '.json', '.xml', '.yaml', '.yml', '.md', '.sql'];

          const isValidType = validTypes.some(t => file.type.startsWith(t));
          const isValidExt = validExts.some(ext => file.name.toLowerCase().endsWith(ext));

          if (!isValidType && !isValidExt) {
              // Custom Alert instead of window.alert
              showAlert(t.fileError, t.fileHint, 'error');
              if (fileInputRef.current) fileInputRef.current.value = '';
              return;
          }

          const formData = new FormData();
          formData.append('image', file);

          try {
              const res = await fetch('/api/upload', { method: 'POST', body: formData });
              const data = await res.json();

              const newAtt: AIAttachment = {
                  id: data.id,
                  type: file.type.startsWith('image/') ? 'image' : 'file',
                  url: data.url,
                  filename: data.filename,
                  mimeType: data.mimeType || file.type
              };
              setAttachments(prev => [...prev, newAtt]);
          } catch (e) { 
              console.error(e); 
              showAlert(t.uploadFail, "Please check console or server logs.", 'error'); 
          }
      }
  };

  // --- Voice Input (STT) ---
  const startRecording = async () => {
      try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          const mediaRecorder = new MediaRecorder(stream);
          mediaRecorderRef.current = mediaRecorder;
          const chunks: Blob[] = [];

          mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
          mediaRecorder.onstop = async () => {
              const blob = new Blob(chunks, { type: 'audio/webm' }); 
              const formData = new FormData();
              formData.append('audio', blob, 'voice_input.webm');

              setIsLoading(true); 
              try {
                  const res = await fetch('/api/ai/transcribe', { method: 'POST', headers: { 'api-key': 'internal' }, body: formData });
                  const data = await res.json();
                  if (data.text) {
                      handleSend(data.text); 
                  }
              } catch (e) { console.error(e); } finally { setIsLoading(false); }
          };

          mediaRecorder.start();
          setIsRecording(true);
      } catch (e) { 
          showAlert(t.micError, t.micHint, 'error');
      }
  };

  const stopRecording = () => {
      mediaRecorderRef.current?.stop();
      setIsRecording(false);
  };

  // --- TTS ---
  const playTTS = async (text: string) => {
      try {
          const cleanText = text.replace(/!\[.*?\]\(.*?\)/g, '');

          const res = await fetch('/api/ai/tts', { 
              method: 'POST', 
              headers: { 'Content-Type': 'application/json' }, 
              body: JSON.stringify({ text: cleanText }) 
          });
          const data = await res.json();
          if (data.audio) {
              const audio = new Audio(`data:audio/wav;base64,${data.audio}`);
              audio.play();
          }
      } catch (e) { console.error(e); }
  };

  // --- Render Helpers ---
  const renderMessageContent = (text: string) => {
      const parts = text.split(/(!\[.*?\]\(.*?\))/g);
      return parts.map((part, index) => {
          const imgMatch = part.match(/!\[(.*?)\]\((.*?)\)/);
          if (imgMatch) {
              const alt = imgMatch[1];
              const url = imgMatch[2];

              if (url.endsWith('.mp4') || alt.toLowerCase().includes('video')) {
                   return (
                      <div key={index} className="my-2 rounded-lg overflow-hidden border border-purple-600 shadow-lg relative group">
                          <video src={url} controls className="w-full max-h-64 bg-black/50" />
                          <div className="bg-purple-900/50 p-1 text-[10px] text-purple-300 font-code text-center">GENERATED_VEO_ASSET</div>
                      </div>
                   );
              }

              return (
                  <div key={index} className="my-2 rounded-lg overflow-hidden border border-slate-600 shadow-lg">
                      <img src={url} alt={alt} className="w-full max-h-64 object-contain bg-black/20" />
                      <div className="bg-slate-900/50 p-1 text-[10px] text-slate-500 font-code text-center">GENERATED_ASSET</div>
                  </div>
              );
          }
          return <span key={index}>{part}</span>;
      });
  };

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  const currentMeta = modelMeta[model] || { cost: 0, iq: 0, speed: 0 };

  return (
    <div className="flex h-full bg-[#020617] text-slate-200 overflow-hidden font-sans relative">

      {/* --- CUSTOM ALERT MODAL --- */}
      {alertModal.show && (
          <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-200">
              <div className={`max-w-md w-full bg-slate-900 p-1 relative border-2 ${alertModal.type === 'error' ? 'border-rose-600 shadow-[0_0_40px_rgba(225,29,72,0.4)]' : 'border-cyan-500 shadow-[0_0_40px_rgba(6,182,212,0.4)]'}`}>
                  {/* Decorative corners */}
                  <div className={`absolute top-0 left-0 w-2 h-2 ${alertModal.type==='error'?'bg-rose-500':'bg-cyan-500'}`}></div>
                  <div className={`absolute top-0 right-0 w-2 h-2 ${alertModal.type==='error'?'bg-rose-500':'bg-cyan-500'}`}></div>
                  <div className={`absolute bottom-0 left-0 w-2 h-2 ${alertModal.type==='error'?'bg-rose-500':'bg-cyan-500'}`}></div>
                  <div className={`absolute bottom-0 right-0 w-2 h-2 ${alertModal.type==='error'?'bg-rose-500':'bg-cyan-500'}`}></div>

                  <div className="bg-[#020617] p-6 relative overflow-hidden">
                      {/* Scanline bg */}
                      <div className="absolute inset-0 opacity-10 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_2px,3px_100%] pointer-events-none"></div>

                      <h3 className={`text-xl font-tech font-black uppercase tracking-widest mb-4 flex items-center gap-3 ${alertModal.type === 'error' ? 'text-rose-500' : 'text-cyan-400'}`}>
                          <span className="text-2xl">{alertModal.type === 'error' ? '⚠️' : 'ℹ️'}</span>
                          {alertModal.title}
                      </h3>

                      <div className={`h-px w-full mb-4 ${alertModal.type === 'error' ? 'bg-rose-900' : 'bg-cyan-900'}`}></div>

                      <p className="font-code text-sm text-slate-300 leading-relaxed whitespace-pre-line mb-8">
                          {alertModal.message}
                      </p>

                      <button 
                        onClick={() => setAlertModal(prev => ({ ...prev, show: false }))}
                        className={`w-full py-3 font-bold font-tech uppercase tracking-[0.2em] text-xs transition-all relative group overflow-hidden ${
                          alertModal.type === 'error' 
                          ? 'bg-rose-950 text-rose-500 border border-rose-800 hover:bg-rose-900 hover:text-rose-300' 
                          : 'bg-cyan-950 text-cyan-500 border border-cyan-800 hover:bg-cyan-900 hover:text-cyan-300'
                        }`}
                      >
                        <span className="relative z-10">{t.ack}</span>
                        <div className={`absolute inset-0 translate-y-full group-hover:translate-y-0 transition-transform duration-300 ${alertModal.type==='error'?'bg-rose-500/10':'bg-cyan-500/10'}`}></div>
                      </button>
                  </div>
              </div>
          </div>
       )}

      {/* --- SIDEBAR --- */}
      <div className="w-16 md:w-64 flex flex-col bg-slate-900/50 border-r border-cyan-900/30 backdrop-blur-md z-20 transition-all">
        <div className="p-4 flex flex-col gap-2">
          <button onClick={() => createSession('general')} className="w-full flex items-center justify-center md:justify-start gap-3 px-3 py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-tech text-xs tracking-widest uppercase shadow-lg transition-all clip-button">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            <span className="hidden md:inline">{t.newChat}</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
           <div className="hidden md:block text-[10px] text-slate-500 font-code uppercase tracking-widest mb-2 px-2">{t.history}</div>
           <div className="space-y-1">
             {sessions.map(s => (
               <div key={s.id} onClick={() => setCurrentSessionId(s.id)} className={`group relative p-2 md:p-3 cursor-pointer border-l-2 transition-all ${currentSessionId === s.id ? 'bg-slate-800 border-cyan-500 text-cyan-100' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}>
                  <div className="flex justify-between items-center">
                      <div className="font-bold text-xs truncate w-full pr-6">{s.title || "Untitled Link"}</div>
                      <button onClick={(e) => deleteSession(s.id, e)} className="absolute right-2 opacity-0 group-hover:opacity-100 text-slate-600 hover:text-rose-500">×</button>
                  </div>
                  <div className="hidden md:block text-[10px] font-code truncate opacity-70 mt-1">{s.preview}</div>
                  <div className="hidden md:flex gap-2 mt-1">
                      <span className={`text-[8px] px-1 rounded border ${s.mode==='coder'?'border-purple-500 text-purple-400':s.mode==='analyst'?'border-emerald-500 text-emerald-400':'border-slate-600'}`}>{s.mode.toUpperCase()}</span>
                  </div>
               </div>
             ))}
           </div>
