import { StockAnalysisResult, Language, OHLC, BacktestResult, Trade } from '../types';

interface ExtendedStockResult extends StockAnalysisResult {
  isCached?: boolean;
  dataSource?: string;
}

interface StockDashboardProps {
  lang: Language;
}

type IndicatorType = 'VOL' | 'MACD' | 'AMT';

