      search: "查询",
      marketData: "市场实时概览",
      aiAnalyze: "AI 神经诊断",
      backtest: "策略实验室 / 回测",
      runBt: "执行回测",
      btParams: "回测参数配置",
      capital: "初始资金",
      commission: "手续费率",
      strategy: "策略选择",
      startDate: "开始日期",
      endDate: "结束日期",
      finalValue: "最终资金",
      totalReturn: "累计收益",
      maxDD: "最大回撤",
